var EXAMS_BASE = [{"id": "2027-g6-p1-quiz", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 1", "titulo": "Quiz — Atletismo: pruebas y movimientos básicos (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "¿Qué es el atletismo?", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El atletismo es conocido como el «deporte base» porque reúne los movimientos naturales del ser humano: correr, saltar y lanzar. Sus pruebas se dividen en dos grandes grupos. Las pruebas de pista se realizan sobre un óvalo de 400 metros dividido en carriles: allí están las carreras de velocidad (100, 200 y 400 metros), las de medio fondo y fondo (800, 1500, 5000 metros y más), las carreras con vallas y los relevos. Las pruebas de campo se realizan en zonas especiales: los saltos (largo, triple, alto y con garrocha) y los lanzamientos (bala, disco, jabalina y martillo).<br><br>Para practicar atletismo no basta con tener fuerza o velocidad. El cuerpo necesita coordinación, es decir, que brazos, piernas y tronco se muevan de forma ordenada; equilibrio, para no perder el control al apoyar el pie o al caer de un salto; y una buena postura, que permite usar la energía sin desperdiciarla. Por eso, en las primeras clases se trabaja con juegos de carrera, saltos sobre aros y lanzamientos de pelotas pequeñas, antes de usar implementos oficiales. Antes de cualquier práctica se realiza un calentamiento que prepara músculos y articulaciones y disminuye el riesgo de lesiones."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el atletismo se llama «deporte base» porque:", "opciones": {"A": "es el deporte más antiguo de los Juegos Olímpicos.", "B": "reúne los movimientos naturales de correr, saltar y lanzar.", "C": "se practica únicamente en pistas de 400 metros.", "D": "no necesita ningún tipo de calentamiento."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál de las siguientes es una prueba de campo?", "opciones": {"A": "Los relevos.", "B": "El salto largo.", "C": "Los 100 metros planos.", "D": "Los 1500 metros."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "La pista oficial de atletismo tiene una vuelta de:", "opciones": {"A": "100 metros.", "B": "1000 metros.", "C": "200 metros.", "D": "400 metros."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la palabra «coordinación» significa:", "opciones": {"A": "que brazos, piernas y tronco se muevan de forma ordenada.", "B": "que el cuerpo permanezca quieto antes de la salida.", "C": "que el atleta corra siempre a la máxima velocidad.", "D": "que el atleta use implementos oficiales desde la primera clase."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué en las primeras clases se usan aros y pelotas pequeñas en lugar de implementos oficiales?", "opciones": {"A": "Porque las pelotas pequeñas pesan más que una bala oficial.", "B": "Porque el atletismo escolar no tiene pruebas de lanzamiento.", "C": "Porque primero se aprende el movimiento con materiales más fáciles y seguros.", "D": "Porque los implementos oficiales están prohibidos en los colegios."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante cae desequilibrado cada vez que termina un salto. ¿Qué capacidad necesita reforzar principalmente?", "opciones": {"A": "El equilibrio.", "B": "La velocidad de reacción.", "C": "La fuerza de los brazos.", "D": "La resistencia aeróbica."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "Las carreras de 100, 200 y 400 metros pertenecen al grupo de:", "opciones": {"A": "velocidad.", "B": "saltos.", "C": "lanzamientos.", "D": "fondo."}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Según el texto, una buena postura ayuda al atleta porque:", "opciones": {"A": "le evita entrenar la coordinación.", "B": "le permite usar la energía sin desperdiciarla.", "C": "reemplaza el calentamiento.", "D": "lo hace más alto que sus compañeros."}}, {"n": 9, "seccion": 1, "competencia": "Aplicación", "enunciado": "Antes de una práctica de carreras, lo más adecuado es:", "opciones": {"A": "estirar solo después de terminar la carrera.", "B": "correr de inmediato a máxima velocidad.", "C": "saltar en un pie durante diez minutos sin parar.", "D": "hacer un calentamiento que prepare músculos y articulaciones."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del texto?", "opciones": {"A": "El atletismo solo es para personas con mucha fuerza.", "B": "Las pruebas de campo son más importantes que las de pista.", "C": "El atletismo reúne movimientos básicos que requieren coordinación, equilibrio y postura.", "D": "El calentamiento es la parte más larga de una clase."}}], "modalidad": "Quiz"}, {"id": "2027-g6-p1", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Atletismo: postura, coordinación y equilibrio (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "La postura y la técnica de carrera", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Correr parece sencillo, pero una buena técnica marca la diferencia. El tronco debe ir erguido y ligeramente inclinado hacia adelante, sin encorvar la espalda. La cabeza se mantiene alineada con el tronco y la mirada al frente, no hacia el suelo. Los brazos se doblan aproximadamente en ángulo recto (90 grados) y se mueven de adelante hacia atrás, al lado del cuerpo, en sentido contrario a las piernas: cuando avanza la pierna derecha, avanza el brazo izquierdo. Este movimiento cruzado se llama coordinación contralateral y ayuda a mantener el equilibrio.<br><br>En las carreras de velocidad, el pie apoya primero con la parte delantera (el metatarso) y no con el talón, lo que permite impulsarse más rápido. La rodilla sube al frente y el pie de atrás empuja el suelo con fuerza. Los hombros deben ir relajados: la tensión en el cuello y en las manos gasta energía y hace la carrera más lenta. Un error frecuente es mover los brazos cruzándolos delante del pecho, lo que hace girar el tronco y desvía la dirección."}, {"id": 2, "titulo": "La salida y la ubicación en el espacio", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "En las carreras de velocidad la salida es decisiva. Los atletas usan la salida baja, apoyando los pies en unos bloques llamados tacos de salida. El juez da tres señales: «¡A sus puestos!», cuando el atleta se ubica con las manos detrás de la línea; «¡Listos!», cuando eleva la cadera y queda inmóvil; y el disparo, que indica el inicio. Si un atleta sale antes del disparo comete una salida en falso, y según el reglamento internacional queda descalificado.<br><br>Cada corredor debe permanecer en su carril durante las pruebas de 100 metros. En la curva, los carriles exteriores parecen ir adelante; en realidad, esa ventaja compensa la mayor distancia que deben recorrer, y por eso las salidas están escalonadas. Ubicarse bien en el espacio y en el tiempo —saber dónde está el carril, cuándo acelerar y cuándo mantener la velocidad— es tan importante como la fuerza de las piernas. A esta habilidad se le llama ubicación espacio-temporal."}, {"id": 3, "titulo": "El salto largo: equilibrio en el aire y en la caída", "instruccion": "(Responda las preguntas 15 a 20 con base en el siguiente texto.)", "cuerpo": "El salto largo tiene cuatro fases: la carrera de impulso, la batida, el vuelo y la caída. En la carrera de impulso el atleta acelera de forma progresiva para llegar a la tabla de batida con la máxima velocidad que pueda controlar. La batida se hace con un solo pie, sin pisar más allá de la línea; si la pisa o la sobrepasa, el salto es nulo. Durante el vuelo, los brazos ayudan a mantener el equilibrio y a llevar las piernas hacia adelante. En la caída, el atleta flexiona las rodillas para amortiguar el impacto y lleva el cuerpo hacia adelante para no caer sentado hacia atrás.<br><br>La marca se mide desde la línea de batida hasta la huella más cercana que deja el cuerpo en la arena. Por eso, si el atleta apoya una mano detrás de los pies al caer, pierde distancia. El salto largo exige coordinar velocidad, fuerza y equilibrio en pocos segundos."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, durante la carrera los brazos deben:", "opciones": {"A": "cruzarse delante del pecho en cada paso.", "B": "permanecer quietos para no gastar energía.", "C": "moverse de adelante hacia atrás, al lado del cuerpo.", "D": "moverse hacia arriba y hacia abajo por encima de la cabeza."}}, {"n": 2, "seccion": 1, "competencia": "Lexical", "enunciado": "La expresión «coordinación contralateral» se refiere a:", "opciones": {"A": "mover los dos brazos al mismo tiempo hacia adelante.", "B": "alternar carreras rápidas y lentas en una misma prueba.", "C": "correr siempre por el lado izquierdo de la pista.", "D": "mover el brazo de un lado al mismo tiempo que la pierna del lado contrario."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "En las carreras de velocidad, el pie apoya primero con:", "opciones": {"A": "el talón.", "B": "la parte delantera del pie (metatarso).", "C": "el borde externo del pie.", "D": "toda la planta al mismo tiempo."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué cruzar los brazos delante del pecho es un error?", "opciones": {"A": "Porque está prohibido por el reglamento.", "B": "Porque hace girar el tronco y desvía la dirección de la carrera.", "C": "Porque obliga a apoyar el talón.", "D": "Porque impide respirar durante la carrera."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero corre con los hombros tensos y las manos apretadas. ¿Qué le recomendarías?", "opciones": {"A": "Relajar hombros y manos para no gastar energía de más.", "B": "Correr con los brazos estirados.", "C": "Apretar más fuerte para ganar velocidad.", "D": "Mirar al suelo para concentrarse."}}, {"n": 6, "seccion": 1, "competencia": "Literal", "enunciado": "¿Hacia dónde debe dirigirse la mirada durante la carrera?", "opciones": {"A": "Hacia los corredores de los lados.", "B": "Al frente.", "C": "Hacia el cielo.", "D": "Al suelo, cerca de los pies."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál enunciado resume mejor el primer texto?", "opciones": {"A": "Correr rápido depende solo de la fuerza de las piernas.", "B": "La técnica de carrera solo importa en las pruebas largas.", "C": "Una buena postura y el movimiento correcto de brazos y piernas hacen la carrera más eficiente.", "D": "Los brazos no influyen en la velocidad de un atleta."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál es el orden correcto de las señales del juez en la salida?", "opciones": {"A": "«¡Ya!», «¡Listos!» y «¡Fuera!».", "B": "«¡Listos!», «¡A sus puestos!» y el disparo.", "C": "«¡A sus puestos!», «¡Listos!» y el disparo.", "D": "El disparo, «¡Listos!» y «¡A sus puestos!»."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "Según el texto, un atleta que sale antes del disparo:", "opciones": {"A": "queda descalificado.", "B": "recibe una advertencia y repite la salida.", "C": "debe salir desde el último carril.", "D": "pierde un segundo en su tiempo final."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "Las salidas escalonadas en las carreras con curva existen porque:", "opciones": {"A": "así el público puede ver mejor la carrera.", "B": "el juez necesita más espacio para dar las señales.", "C": "los atletas más rápidos se ubican adelante.", "D": "los carriles exteriores recorren más distancia en la curva."}}, {"n": 11, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, «ubicación espacio-temporal» significa:", "opciones": {"A": "conocer la historia del atletismo.", "B": "elegir el carril que más te guste.", "C": "saber dónde estás y cuándo hacer cada acción durante la prueba.", "D": "calcular la distancia total de la pista."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "En la posición de «¡Listos!», el atleta debe:", "opciones": {"A": "empezar a correr suavemente.", "B": "ponerse de pie completamente.", "C": "mover los brazos para calentar.", "D": "elevar la cadera y quedarse inmóvil."}}, {"n": 13, "seccion": 2, "competencia": "Inferencial", "enunciado": "Durante una carrera de 100 metros, si un corredor se pasa al carril de al lado, lo más probable es que:", "opciones": {"A": "deba repetir la salida.", "B": "incumpla la regla de permanecer en su carril.", "C": "gane ventaja legalmente.", "D": "reciba más tiempo para terminar."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Según el segundo texto, ¿qué es tan importante como la fuerza de las piernas?", "opciones": {"A": "La ubicación en el espacio y en el tiempo durante la carrera.", "B": "El tipo de tacos de salida.", "C": "La altura del atleta.", "D": "El color del uniforme."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Cuáles son las cuatro fases del salto largo?", "opciones": {"A": "Calentamiento, carrera, salto y descanso.", "B": "Salida, aceleración, llegada y medición.", "C": "Batida, carrera, caída y vuelo.", "D": "Carrera de impulso, batida, vuelo y caída."}}, {"n": 16, "seccion": 3, "competencia": "Literal", "enunciado": "La batida en el salto largo se realiza:", "opciones": {"A": "después de la línea de batida.", "B": "con las manos apoyadas en la tabla.", "C": "con los dos pies juntos.", "D": "con un solo pie, sin pasar la línea."}}, {"n": 17, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué el atleta flexiona las rodillas al caer?", "opciones": {"A": "Para ganar velocidad en la carrera de impulso.", "B": "Porque el reglamento lo exige para que el salto sea válido.", "C": "Para amortiguar el impacto y no perder el equilibrio.", "D": "Para medir mejor su salto."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Un atleta salta 4 metros pero al caer apoya una mano detrás de los pies. ¿Qué pasa con su marca?", "opciones": {"A": "Se mide hasta los pies y no cuenta la mano.", "B": "Se mide hasta la huella de la mano, porque es la más cercana a la línea.", "C": "Se le suman los centímetros de la mano.", "D": "El salto queda anulado automáticamente."}}, {"n": 19, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, la palabra «nulo» significa que el salto:", "opciones": {"A": "no es válido.", "B": "fue realizado sin carrera.", "C": "fue el más largo.", "D": "debe medirse dos veces."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué tienen en común los tres textos?", "opciones": {"A": "Muestran que en el atletismo la técnica, el equilibrio y la ubicación son tan importantes como la fuerza.", "B": "Describen solo las pruebas de lanzamiento.", "C": "Explican la historia de los Juegos Olímpicos.", "D": "Afirman que el atletismo no necesita entrenamiento."}}]}, {"id": "2027-g7-p1-quiz", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 1", "titulo": "Quiz — Futsal: origen y reglas básicas (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Un deporte nacido en Sudamérica", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El fútbol de salón o futsal nació en 1930 en Montevideo, Uruguay. El profesor Juan Carlos Ceriani adaptó el fútbol a canchas pequeñas y cerradas para que los jóvenes pudieran jugar en cualquier época del año. Hoy el futsal está reglamentado por la FIFA y se juega en todo el mundo; Colombia ha tenido selecciones destacadas en esta disciplina.<br><br>Cada equipo tiene cinco jugadores en la cancha, uno de ellos el portero. El partido dura dos tiempos de 20 minutos de juego cronometrado: el reloj se detiene cada vez que el balón sale o el árbitro para el juego. El balón es más pequeño y pesado que el del fútbol (tamaño 4) y rebota menos, lo que favorece jugarlo por el suelo y controlarlo con la planta del pie. Los cambios son ilimitados y «volantes»: un jugador puede salir y volver a entrar varias veces, siempre por la zona de sustitución. Cuando el balón sale por la banda, el juego se reanuda con un saque con el pie, no con las manos, y el jugador tiene cuatro segundos para hacerlo. Estas reglas hacen que el futsal sea rápido, técnico y con muchos toques de balón."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué país nació el futsal?", "opciones": {"A": "España.", "B": "Uruguay.", "C": "Brasil.", "D": "Colombia."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores tiene cada equipo en la cancha?", "opciones": {"A": "Cinco, incluido el portero.", "B": "Seis, incluido el portero.", "C": "Once, igual que en el fútbol.", "D": "Siete, sin contar el portero."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto dura cada tiempo de un partido de futsal?", "opciones": {"A": "20 minutos de juego cronometrado.", "B": "10 minutos cronometrados.", "C": "45 minutos corridos.", "D": "30 minutos con el reloj sin detener."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "Que el tiempo sea «cronometrado» significa que:", "opciones": {"A": "el reloj se detiene cada vez que el juego se para.", "B": "el árbitro decide cuánto dura el partido.", "C": "cada equipo controla su propio tiempo.", "D": "el reloj nunca se detiene."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el balón de futsal favorece el juego por el suelo?", "opciones": {"A": "Porque la cancha es de arena.", "B": "Porque es más liviano que el de fútbol.", "C": "Porque es más pequeño y pesado, y rebota menos.", "D": "Porque está prohibido elevar el balón."}}, {"n": 6, "seccion": 1, "competencia": "Literal", "enunciado": "Cuando el balón sale por la banda, el juego se reanuda:", "opciones": {"A": "con un tiro libre desde el centro.", "B": "con un saque con el pie.", "C": "con un bote neutral del árbitro.", "D": "con un saque con las manos."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto tiempo tiene el jugador para hacer el saque de banda?", "opciones": {"A": "Seis segundos.", "B": "Cuatro segundos.", "C": "No hay límite de tiempo.", "D": "Diez segundos."}}, {"n": 8, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, los cambios «volantes» son aquellos en los que:", "opciones": {"A": "el cambio lo decide el árbitro.", "B": "el jugador que sale no puede regresar.", "C": "un jugador puede salir y volver a entrar varias veces.", "D": "solo se permiten tres cambios por partido."}}, {"n": 9, "seccion": 1, "competencia": "Aplicación", "enunciado": "Durante un partido, tu equipo quiere hacer un cambio. ¿Qué debe respetar?", "opciones": {"A": "Que el jugador que entra sea el portero.", "B": "Que el partido esté en el segundo tiempo.", "C": "Que el árbitro detenga el reloj.", "D": "Que el cambio se haga por la zona de sustitución."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, ¿por qué el futsal es un deporte rápido y técnico?", "opciones": {"A": "Porque los partidos son más largos.", "B": "Porque no tiene reglas oficiales.", "C": "Porque se juega con más jugadores que el fútbol.", "D": "Porque sus reglas favorecen muchos toques de balón y un juego continuo."}}], "modalidad": "Quiz"}, {"id": "2027-g7-p1", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Futsal: fundamentos técnicos (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "La conducción y el control del balón", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "En el futsal el espacio es reducido y los rivales están cerca, por eso dominar el balón es fundamental. La conducción consiste en avanzar con el balón controlado. En la cancha pequeña se conduce mucho con la planta del pie, que permite frenar, arrastrar el balón hacia atrás o hacia los lados y cambiar de dirección rápidamente. También se usan el borde interno y el borde externo del pie. Durante la conducción, el jugador debe levantar la cabeza para observar a sus compañeros y a los rivales, y mantener el balón cerca del pie para protegerlo.<br><br>El control o recepción es la acción de dominar un balón que llega. Un buen control «amortigua» el balón: el pie retrocede un poco en el momento del contacto para quitarle velocidad, igual que cuando se atrapa un huevo con la mano. Si el pie queda rígido, el balón rebota lejos y se pierde la posesión. Antes de recibir, el jugador experto ya ha mirado el espacio libre, de modo que el primer toque deja el balón listo para la siguiente acción."}, {"id": 2, "titulo": "El pase y el remate", "instruccion": "(Responda las preguntas 8 a 13 con base en el siguiente texto.)", "cuerpo": "El pase es la acción técnica más usada en el futsal. El pase con el borde interno del pie es el más preciso, porque la superficie de contacto es amplia; se usa para distancias cortas y medias. El pie de apoyo se coloca al lado del balón, apuntando hacia el compañero, y el tobillo se mantiene firme. El pase con la planta y el pase con la punta del pie se usan para jugadas rápidas en espacios muy reducidos.<br><br>El remate es el golpe al balón con intención de hacer gol. En el futsal se remata mucho con la punta del pie (puntera), porque es un golpe rápido que casi no necesita impulso y sorprende al portero. El remate con el empeine es más potente, pero necesita más espacio y tiempo. Para rematar bien, el jugador mira la portería, ubica al portero y elige el lado contrario a su posición. La precisión es más importante que la fuerza: un remate suave y bien dirigido suele ser más efectivo que un golpe fuerte sin dirección."}, {"id": 3, "titulo": "Reglas que influyen en la técnica", "instruccion": "(Responda las preguntas 14 a 20 con base en el siguiente texto.)", "cuerpo": "El reglamento del futsal cambia la forma de jugar. Como el saque de banda se hace con el pie, los equipos ensayan jugadas preparadas a partir de él. El portero, cuando controla el balón en su propia mitad, tiene solo cuatro segundos para jugarlo, lo que lo obliga a pensar rápido y a tener buena técnica con los pies. Además, las faltas se acumulan: a partir de la sexta falta acumulada de un equipo en cada tiempo, el rival cobra un tiro libre directo sin barrera desde el segundo punto penal, ubicado a 10 metros de la portería. El primer punto penal está a 6 metros.<br><br>Por esta regla, los jugadores aprenden a defender sin cometer faltas: se colocan entre el rival y la portería, flexionan las piernas y esperan el momento adecuado para quitar el balón. En el futsal la barrida (lanzarse al suelo para quitar el balón) está muy restringida: si se hace de forma imprudente o temeraria contra un rival, se sanciona como falta."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿qué superficie del pie se usa mucho para conducir en el futsal?", "opciones": {"A": "La planta del pie.", "B": "Solo la punta del pie.", "C": "La rodilla.", "D": "El talón."}}, {"n": 2, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el jugador debe levantar la cabeza mientras conduce?", "opciones": {"A": "Para evitar mirar el balón.", "B": "Para observar a compañeros y rivales y decidir mejor.", "C": "Porque el reglamento lo exige.", "D": "Para correr más rápido."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «amortiguar» el balón significa:", "opciones": {"A": "patearlo con más fuerza.", "B": "levantarlo por encima de la cabeza.", "C": "dejarlo rebotar en la pared.", "D": "quitarle velocidad en el momento de recibirlo."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "Si un jugador recibe el balón con el pie rígido, lo más probable es que:", "opciones": {"A": "el balón quede pegado al pie.", "B": "el balón rebote lejos y se pierda la posesión.", "C": "el árbitro sancione una falta.", "D": "haga un pase perfecto."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Vas a recibir un pase y un rival se acerca rápido. Según el texto, ¿qué deberías hacer antes de recibir?", "opciones": {"A": "Pedir al árbitro que detenga el juego.", "B": "Esperar quieto a que llegue el balón.", "C": "Cerrar los ojos para concentrarte.", "D": "Mirar el espacio libre para que el primer toque prepare la siguiente acción."}}, {"n": 6, "seccion": 1, "competencia": "Literal", "enunciado": "¿Por qué se compara el control del balón con atrapar un huevo?", "opciones": {"A": "Porque se debe hacer muy rápido.", "B": "Porque en ambos casos hay que ceder un poco para no rebotar o romper.", "C": "Porque el balón de futsal es frágil.", "D": "Porque se recibe con las manos."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal del primer texto?", "opciones": {"A": "Dominar la conducción y el control es clave en un espacio reducido.", "B": "En el futsal no es importante controlar el balón.", "C": "Solo los porteros necesitan buena técnica.", "D": "El futsal se juega principalmente por el aire."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál es el pase más preciso, según el texto?", "opciones": {"A": "El pase con el borde interno del pie.", "B": "El pase con la cabeza.", "C": "El pase con el talón.", "D": "El pase con el empeine."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "Al hacer un pase con el borde interno, el pie de apoyo se coloca:", "opciones": {"A": "lejos del balón, a un metro.", "B": "encima del balón.", "C": "al lado del balón, apuntando hacia el compañero.", "D": "detrás del balón, apuntando hacia atrás."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué el remate de puntera es frecuente en el futsal?", "opciones": {"A": "Porque es rápido, necesita poco impulso y sorprende al portero.", "B": "Porque es el único remate permitido.", "C": "Porque siempre va por arriba.", "D": "Porque es el remate más potente que existe."}}, {"n": 11, "seccion": 2, "competencia": "Aplicación", "enunciado": "Estás frente al arco y el portero se cubre el lado derecho. ¿Qué te recomienda el texto?", "opciones": {"A": "Rematar hacia el lado donde está el portero.", "B": "Patear lo más fuerte posible hacia el centro.", "C": "Rematar con precisión hacia el lado contrario a su posición.", "D": "Devolver el balón a tu portero."}}, {"n": 12, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, el término «empeine» se refiere a:", "opciones": {"A": "la parte inferior del pie.", "B": "la punta de los dedos.", "C": "el borde externo del tobillo.", "D": "la parte superior del pie."}}, {"n": 13, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Según el segundo texto, ¿qué es más importante en el remate?", "opciones": {"A": "Rematar desde lejos.", "B": "Rematar siempre con el empeine.", "C": "La fuerza sin dirección.", "D": "La precisión."}}, {"n": 14, "seccion": 3, "competencia": "Literal", "enunciado": "¿Cuánto tiempo tiene el portero para jugar el balón cuando lo controla en su propia mitad?", "opciones": {"A": "Diez segundos.", "B": "No tiene límite.", "C": "Seis segundos.", "D": "Cuatro segundos."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Desde qué distancia se cobra el tiro libre a partir de la sexta falta acumulada?", "opciones": {"A": "Desde el primer punto penal, a 6 metros.", "B": "Desde la mitad de la cancha.", "C": "Desde el segundo punto penal, a 10 metros.", "D": "Desde donde se cometió la falta, con barrera."}}, {"n": 16, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué la regla de las faltas acumuladas cambia la forma de defender?", "opciones": {"A": "Porque solo el portero puede defender.", "B": "Porque obliga a quitar el balón sin cometer faltas.", "C": "Porque elimina la defensa.", "D": "Porque permite hacer más barridas."}}, {"n": 17, "seccion": 3, "competencia": "Aplicación", "enunciado": "Tu equipo lleva cinco faltas acumuladas en el primer tiempo. ¿Qué actitud defensiva es la más conveniente?", "opciones": {"A": "Barrerse con fuerza en cada jugada.", "B": "Empujar al rival para que pierda el balón.", "C": "Ubicarse entre el rival y la portería y esperar el momento para quitar el balón.", "D": "Dejar de defender hasta el segundo tiempo."}}, {"n": 18, "seccion": 3, "competencia": "Lexical", "enunciado": "En el texto, una barrida «temeraria» es una acción:", "opciones": {"A": "muy lenta y cuidadosa.", "B": "permitida por el reglamento.", "C": "realizada sin considerar el peligro para el rival.", "D": "que solo puede hacer el portero."}}, {"n": 19, "seccion": 3, "competencia": "Literal", "enunciado": "¿A qué distancia de la portería está el primer punto penal?", "opciones": {"A": "A 9 metros.", "B": "A 6 metros.", "C": "A 11 metros.", "D": "A 10 metros."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué relación hay entre los tres textos?", "opciones": {"A": "Las reglas del futsal y el espacio reducido exigen una técnica precisa con el balón.", "B": "El reglamento del futsal no influye en la forma de jugar.", "C": "Los tres textos tratan sobre la historia del futsal.", "D": "El futsal se gana con fuerza física más que con técnica."}}]}, {"id": "2027-g8-p1-quiz", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 1", "titulo": "Quiz — Voleibol: origen y reglas básicas (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Del Mintonette al voleibol", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "En 1895, William G. Morgan, profesor en Holyoke (Estados Unidos), creó un juego para personas que buscaban una actividad menos brusca que el baloncesto. Lo llamó Mintonette; poco después se le cambió el nombre por volleyball, porque el balón se golpeaba «al vuelo», sin dejarlo caer. Hoy lo reglamenta la Federación Internacional de Voleibol (FIVB).<br><br>Cada equipo tiene seis jugadores en la cancha, separados del rival por una red. En la categoría de mayores, la red mide 2,43 metros de altura para los hombres y 2,24 metros para las mujeres. Cada equipo puede tocar el balón máximo tres veces antes de pasarlo al otro lado (el toque de bloqueo no se cuenta) y un mismo jugador no puede tocarlo dos veces seguidas. Se juega con el sistema de punto por jugada (rally point): cada jugada termina con un punto para alguno de los dos equipos, sin importar quién sacó. Un set lo gana el primer equipo que llega a 25 puntos con una diferencia de al menos dos; el partido lo gana quien gana tres sets. Si hay un quinto set, se juega a 15 puntos."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Quién creó el voleibol?", "opciones": {"A": "William G. Morgan.", "B": "Pierre de Coubertin.", "C": "James Naismith.", "D": "Juan Carlos Ceriani."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál fue el primer nombre del voleibol?", "opciones": {"A": "Netball.", "B": "Mintonette.", "C": "Basket-volley.", "D": "Volley."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "El nombre volleyball se relaciona con golpear el balón:", "opciones": {"A": "con los pies.", "B": "con una raqueta.", "C": "después de un bote.", "D": "«al vuelo», sin dejarlo caer."}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores tiene cada equipo en la cancha?", "opciones": {"A": "Once.", "B": "Seis.", "C": "Cinco.", "D": "Siete."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas veces puede tocar el balón un equipo antes de pasarlo, sin contar el bloqueo?", "opciones": {"A": "Dos.", "B": "Las que necesite.", "C": "Tres.", "D": "Cuatro."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador recibe el saque y, sin que nadie más toque el balón, vuelve a golpearlo. ¿Qué ocurre?", "opciones": {"A": "Se repite el saque.", "B": "Es válido, porque fue el primer toque.", "C": "Es válido si el balón no tocó el suelo.", "D": "Es falta, porque un jugador no puede tocar el balón dos veces seguidas."}}, {"n": 7, "seccion": 1, "competencia": "Lexical", "enunciado": "En el sistema «rally point»:", "opciones": {"A": "se juega por tiempo y no por puntos.", "B": "solo puntúa el equipo que saca.", "C": "cada jugada termina con un punto para alguno de los equipos.", "D": "los puntos valen doble en el quinto set."}}, {"n": 8, "seccion": 1, "competencia": "Aplicación", "enunciado": "El marcador de un set va 25 a 24. ¿Qué pasa?", "opciones": {"A": "El set continúa hasta que un equipo saque dos puntos de diferencia.", "B": "El set termina empatado.", "C": "Se juega un set extra.", "D": "Gana el equipo que tiene 25."}}, {"n": 9, "seccion": 1, "competencia": "Literal", "enunciado": "¿A cuántos puntos se juega el quinto set?", "opciones": {"A": "A 21 puntos.", "B": "A 15 puntos.", "C": "A 10 puntos.", "D": "A 25 puntos."}}, {"n": 10, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué Morgan diseñó un juego con red que separa a los equipos?", "opciones": {"A": "Para crear una actividad sin contacto, menos brusca que el baloncesto.", "B": "Para que el juego fuera más violento.", "C": "Porque no había balones disponibles.", "D": "Para que se jugara solo al aire libre."}}], "modalidad": "Quiz"}, {"id": "2027-g8-p1", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Voleibol: coordinación, ritmo y reglamento (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Los golpes básicos: toque de dedos y antebrazos", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El voleibol se juega con golpes, porque el balón no se puede retener ni lanzar. El toque de dedos (o pase alto) se usa para balones que llegan por encima de la cabeza. El jugador se ubica debajo del balón, con las piernas semiflexionadas y un pie un poco adelante; las manos forman una especie de canasta frente a la frente, con los pulgares y los índices formando un triángulo. El balón se toca con las yemas de los dedos y el impulso nace de la extensión coordinada de piernas y brazos, no solo de las muñecas.<br><br>El golpe de antebrazos (o recepción) se usa para balones bajos y para recibir el saque. Los brazos se juntan y se extienden, formando una superficie plana con los antebrazos; las manos se unen sin entrelazar los dedos. El contacto se hace con los antebrazos, por encima de las muñecas, y el movimiento sale de las piernas: los brazos no se balancean por encima de los hombros. La clave de ambos golpes es llegar a tiempo debajo del balón: los desplazamientos cortos y rápidos y el ritmo de los pasos son tan importantes como la posición de las manos."}, {"id": 2, "titulo": "El saque y la rotación", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Cada jugada comienza con un saque desde detrás de la línea de fondo. Después del pitazo del árbitro, el jugador tiene ocho segundos para sacar. El saque de abajo, golpeando el balón con la mano a la altura de la cadera, es el más fácil de aprender; el saque de tenis, golpeando por encima del hombro, es más potente. Durante el saque, el jugador no puede pisar la línea de fondo.<br><br>El voleibol exige que todos los jugadores pasen por todas las posiciones. Cuando un equipo recupera el derecho a sacar, sus jugadores rotan una posición en el sentido de las agujas del reloj, y el jugador que llega a la posición 1 (atrás a la derecha) es quien saca. Si un equipo no está en el orden correcto en el momento del saque, comete una falta de rotación y el rival gana el punto. Esta regla obliga a todos los jugadores a aprender a recibir, pasar y atacar, y a coordinarse con sus compañeros en el espacio."}, {"id": 3, "titulo": "Faltas frecuentes y juego limpio", "instruccion": "(Responda las preguntas 15 a 20 con base en el siguiente texto.)", "cuerpo": "Algunas faltas se repiten mucho en el voleibol escolar. La retención ocurre cuando el balón queda detenido en las manos o es acompañado en lugar de golpeado. El doble contacto ocurre cuando un mismo jugador toca el balón dos veces seguidas (excepto en el bloqueo o en el primer toque del equipo, cuando el contacto es en una misma acción). También es falta tocar la red con cualquier parte del cuerpo mientras se juega el balón, y pasar al campo contrario por debajo de la red interfiriendo con el rival.<br><br>El voleibol tiene una fuerte tradición de juego limpio. Los jugadores levantan la mano para reconocer cuando tocaron la red o el balón antes de que salga, aunque el árbitro no lo haya visto. Después de cada punto, el equipo se reúne unos segundos para animarse, corregir y planear la siguiente jugada. Este ritmo de comunicación constante hace del voleibol un deporte de cooperación: ningún jugador puede ganar solo, porque nadie puede tocar el balón dos veces seguidas."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Para qué balones se usa el toque de dedos?", "opciones": {"A": "Para balones que tocan el suelo.", "B": "Solo para el saque.", "C": "Para balones que llegan a la altura de las rodillas.", "D": "Para balones que llegan por encima de la cabeza."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "En el toque de dedos, el balón se toca con:", "opciones": {"A": "los antebrazos.", "B": "las yemas de los dedos.", "C": "los puños cerrados.", "D": "las palmas de las manos."}}, {"n": 3, "seccion": 1, "competencia": "Inferencial", "enunciado": "Según el texto, el impulso del toque de dedos viene principalmente de:", "opciones": {"A": "un movimiento fuerte de las muñecas.", "B": "la extensión coordinada de piernas y brazos.", "C": "un salto lo más alto posible.", "D": "el movimiento de la cabeza."}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "En el golpe de antebrazos, las manos deben:", "opciones": {"A": "unirse sin entrelazar los dedos.", "B": "quedar separadas.", "C": "entrelazar los dedos con fuerza.", "D": "formar un triángulo frente a la frente."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero recibe el saque balanceando los brazos por encima de los hombros y el balón sale disparado hacia atrás. ¿Qué le corregirías?", "opciones": {"A": "Que el movimiento salga de las piernas y los brazos no suban por encima de los hombros.", "B": "Que reciba con las yemas de los dedos.", "C": "Que se quede quieto y espere el balón.", "D": "Que golpee con los puños cerrados."}}, {"n": 6, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «semiflexionadas» indica que las piernas están:", "opciones": {"A": "cruzadas.", "B": "completamente estiradas.", "C": "levantadas del suelo.", "D": "un poco dobladas."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Según el primer texto, ¿qué es tan importante como la posición de las manos?", "opciones": {"A": "Tener mucha fuerza en los brazos.", "B": "Ser el jugador más alto.", "C": "Llegar a tiempo debajo del balón con desplazamientos y ritmo adecuados.", "D": "Golpear siempre con la mano abierta."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuánto tiempo tiene el jugador para sacar después del pitazo?", "opciones": {"A": "Ocho segundos.", "B": "Cinco segundos.", "C": "Diez segundos.", "D": "Tres segundos."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Desde dónde se realiza el saque?", "opciones": {"A": "Desde la mitad de la cancha.", "B": "Desde cualquier lugar de la cancha.", "C": "Desde detrás de la línea de fondo.", "D": "Junto a la red."}}, {"n": 10, "seccion": 2, "competencia": "Literal", "enunciado": "¿En qué sentido rota el equipo cuando recupera el saque?", "opciones": {"A": "En el sentido de las agujas del reloj.", "B": "De adelante hacia atrás sin orden.", "C": "En sentido contrario a las agujas del reloj.", "D": "Cada jugador elige su posición."}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Cuál es la principal consecuencia educativa de la regla de rotación?", "opciones": {"A": "Los jugadores no necesitan comunicarse.", "B": "El mejor jugador saca siempre.", "C": "Todos los jugadores deben aprender a recibir, pasar y atacar.", "D": "Solo los jugadores altos atacan."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "En el momento del saque, dos jugadores de tu equipo están intercambiados de lugar. ¿Qué ocurre?", "opciones": {"A": "Se repite el saque sin sanción.", "B": "El árbitro les da una advertencia.", "C": "Es válido si nadie lo nota.", "D": "Es falta de rotación y el rival gana el punto."}}, {"n": 13, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, el «saque de tenis» se caracteriza por:", "opciones": {"A": "usar una raqueta.", "B": "lanzar el balón con las dos manos.", "C": "golpear el balón por encima del hombro.", "D": "golpear el balón a la altura de la cadera."}}, {"n": 14, "seccion": 2, "competencia": "Literal", "enunciado": "¿Quién saca después de una rotación?", "opciones": {"A": "El jugador que llega a la posición 1, atrás a la derecha.", "B": "El jugador que hizo el último punto.", "C": "El capitán del equipo.", "D": "El jugador más cercano a la red."}}, {"n": 15, "seccion": 3, "competencia": "Lexical", "enunciado": "En el tercer texto, la «retención» es:", "opciones": {"A": "tocar la red con la mano.", "B": "sacar fuera de la cancha.", "C": "dejar el balón detenido o acompañarlo en lugar de golpearlo.", "D": "rotar en el sentido incorrecto."}}, {"n": 16, "seccion": 3, "competencia": "Literal", "enunciado": "¿Cuándo es válido que un mismo jugador toque el balón dos veces seguidas?", "opciones": {"A": "En el tercer toque del equipo.", "B": "Siempre que el balón no toque el suelo.", "C": "Cuando el equipo va perdiendo.", "D": "En el bloqueo, o en el primer toque del equipo cuando ocurre en una misma acción."}}, {"n": 17, "seccion": 3, "competencia": "Aplicación", "enunciado": "Al rematar cerca de la red, un jugador la roza con la camiseta mientras juega el balón. ¿Qué indica el texto?", "opciones": {"A": "Es falta únicamente en el quinto set.", "B": "Es falta tocar la red mientras se juega el balón.", "C": "Es válido porque fue con la camiseta.", "D": "Solo es falta si la red se cae."}}, {"n": 18, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué el texto dice que en el voleibol «ningún jugador puede ganar solo»?", "opciones": {"A": "Porque los equipos tienen más de diez jugadores.", "B": "Porque nadie puede tocar el balón dos veces seguidas y se necesitan los compañeros.", "C": "Porque el árbitro decide quién gana.", "D": "Porque el balón es muy pesado."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Un jugador levanta la mano para reconocer que tocó la red, aunque el árbitro no lo vio. Esta actitud demuestra:", "opciones": {"A": "miedo a perder.", "B": "desconocimiento del reglamento.", "C": "falta de concentración.", "D": "juego limpio y honestidad."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué idea une los tres textos?", "opciones": {"A": "El voleibol no tiene reglas sobre el saque.", "B": "El voleibol exige coordinación, ritmo y respeto de las reglas en equipo.", "C": "El voleibol se basa en la fuerza individual.", "D": "Solo importa la técnica de los golpes."}}]}, {"id": "2027-g9-p1-quiz", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 1", "titulo": "Quiz — Baloncesto: reglas de tiempo y espacio (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Un juego de reglas y segundos", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El baloncesto fue creado en 1891 por James Naismith en Springfield (Estados Unidos). Hoy la FIBA (Federación Internacional de Baloncesto) establece que cada equipo tiene cinco jugadores en la cancha y que el partido se divide en cuatro cuartos de 10 minutos.<br><br>Varias reglas se refieren al tiempo. Un equipo tiene 24 segundos para lanzar al aro cada vez que tiene la posesión; si no lo hace, pierde el balón. Tiene 8 segundos para pasar el balón de su campo defensivo al campo de ataque. Un atacante no puede permanecer más de 3 segundos seguidos dentro de la zona restringida (la «pintura») del rival. Y un jugador que está siendo marcado de cerca tiene 5 segundos para pasar, lanzar o botar el balón.<br><br>Otras reglas se refieren al movimiento. Es violación de pasos (o caminar) avanzar con el balón en las manos sin botarlo, y es violación de dobles botar, agarrar el balón y volver a botarlo. En cuanto a las faltas, un jugador que comete cinco faltas personales debe salir del partido. Un lanzamiento convertido desde fuera de la línea de 6,75 metros vale tres puntos."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos segundos tiene un equipo para lanzar al aro en cada posesión?", "opciones": {"A": "30 segundos.", "B": "12 segundos.", "C": "24 segundos.", "D": "8 segundos."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánto tiempo tiene un equipo para pasar el balón a su campo de ataque?", "opciones": {"A": "3 segundos.", "B": "8 segundos.", "C": "24 segundos.", "D": "5 segundos."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la «pintura» es:", "opciones": {"A": "la banca de los suplentes.", "B": "la línea de tres puntos.", "C": "el círculo central.", "D": "la zona restringida cerca del aro."}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un pívot atacante se queda 4 segundos seguidos en la pintura del rival. ¿Qué ocurre?", "opciones": {"A": "Comete violación de 3 segundos y pierde el balón.", "B": "Recibe una falta técnica.", "C": "El juego continúa sin sanción.", "D": "Es válido si no tiene el balón."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos cuartos tiene un partido según la FIBA?", "opciones": {"A": "Cuatro cuartos de 10 minutos.", "B": "Cuatro cuartos de 12 minutos.", "C": "Dos tiempos de 20 minutos.", "D": "Tres periodos de 15 minutos."}}, {"n": 6, "seccion": 1, "competencia": "Lexical", "enunciado": "La violación de «dobles» consiste en:", "opciones": {"A": "pasar el balón con dos manos.", "B": "botar, agarrar el balón y volver a botarlo.", "C": "lanzar dos veces seguidas al aro.", "D": "cometer dos faltas personales."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador recibe el balón, da tres pasos sin botarlo y lanza. ¿Qué cometió?", "opciones": {"A": "Violación de pasos (caminar).", "B": "Violación de dobles.", "C": "Falta personal.", "D": "Ninguna, porque lanzó al aro."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué le pasa a un jugador que comete cinco faltas personales?", "opciones": {"A": "Su equipo pierde 5 puntos.", "B": "Recibe un tiro libre en contra.", "C": "Debe salir del partido.", "D": "Debe sentarse un cuarto completo."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Para qué sirve la regla de los 24 segundos?", "opciones": {"A": "Para que los partidos duren más.", "B": "Para dar descanso a los jugadores.", "C": "Para favorecer al equipo que defiende siempre.", "D": "Para que el juego sea dinámico y los equipos no retengan el balón sin atacar."}}, {"n": 10, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos puntos vale un lanzamiento convertido desde fuera de la línea de 6,75 metros?", "opciones": {"A": "Dos puntos.", "B": "Tres puntos.", "C": "Un punto.", "D": "Cuatro puntos."}}], "modalidad": "Quiz"}, {"id": "2027-g9-p1", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Baloncesto: estrategia y táctica (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Principios del ataque", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "En el baloncesto, la técnica individual no basta: el equipo necesita una estrategia, es decir, un plan para conseguir ventaja sobre el rival. En el ataque existen principios básicos. El primero es ocupar bien los espacios: los jugadores se distribuyen por la cancha para que la defensa no pueda cubrirlos a todos y queden líneas de pase abiertas. El segundo es el «pasar y cortar»: el jugador que entrega el balón no se queda quieto, sino que se desplaza rápidamente hacia el aro o hacia un espacio libre para recibir de nuevo.<br><br>El tercer principio es buscar la superioridad numérica, por ejemplo un dos contra uno (2x1). Cuando dos atacantes enfrentan a un solo defensor, el atacante con balón debe atraer al defensor y pasar en el momento justo a su compañero libre. Finalmente, se busca el mejor lanzamiento posible: no el primero que aparece, sino el que tiene más probabilidad de entrar, normalmente cerca del aro o con el lanzador libre de marca. Un equipo que pasa bien el balón obliga a la defensa a moverse más y comete menos pérdidas."}, {"id": 2, "titulo": "Sistemas defensivos", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Las defensas se organizan principalmente de dos maneras. En la defensa individual, cada defensor se responsabiliza de un atacante y lo sigue por toda la cancha; exige buena condición física y concentración, porque cada jugador debe evitar que su rival reciba o avance con facilidad. En la defensa en zona, cada defensor protege un espacio de la cancha. La más conocida es la zona 2-3: dos jugadores adelante, cerca de la línea de tiros libres, y tres atrás, cerca del aro. La zona protege bien el área cercana al aro, pero deja más libres los lanzamientos desde lejos.<br><br>En ambos sistemas existe la «ayuda»: cuando un compañero es superado por su atacante, el defensor más cercano se desplaza para cerrar el camino al aro, y luego el equipo recupera sus posiciones. La comunicación es fundamental: los defensores se avisan con palabras cortas («¡cambio!», «¡ayuda!», «¡bloqueo!»). El rebote defensivo cierra la jugada: si el equipo no recupera el balón después de un lanzamiento fallado del rival, la buena defensa no sirve de nada."}, {"id": 3, "titulo": "El contraataque y la lectura del juego", "instruccion": "(Responda las preguntas 15 a 20 con base en el siguiente texto.)", "cuerpo": "El contraataque es un ataque rápido que se realiza inmediatamente después de recuperar el balón, antes de que el rival organice su defensa. Comienza con el rebote o el robo, sigue con un pase de salida rápido hacia un jugador que corre por la banda y termina con una entrada al aro, muchas veces en situación de superioridad numérica. Para que funcione, los jugadores deben ocupar tres carriles imaginarios: uno central, para el que conduce el balón, y dos laterales, para los que corren por las bandas.<br><br>Leer el juego significa observar lo que hace el rival y tomar la mejor decisión en cada momento. Si la defensa es en zona y deja libres los lanzamientos lejanos, conviene mover rápido el balón y lanzar de media o larga distancia. Si la defensa es individual y un rival es más lento, conviene atacarlo en el uno contra uno. Un buen equipo no repite siempre la misma jugada: se adapta a lo que el adversario le permite y respeta las decisiones del árbitro aunque no las comparta."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «estrategia» significa:", "opciones": {"A": "la habilidad de botar con las dos manos.", "B": "un plan para conseguir ventaja sobre el rival.", "C": "la fuerza física de los jugadores.", "D": "el reglamento oficial del baloncesto."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué consiste el «pasar y cortar»?", "opciones": {"A": "Pasar solo hacia atrás.", "B": "Cortar el pase del rival.", "C": "Después de pasar, el jugador se desplaza hacia el aro o un espacio libre para recibir de nuevo.", "D": "Pasar el balón y quedarse quieto."}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un 2x1, tú llevas el balón y el defensor no se acerca a ti. ¿Qué es lo más conveniente?", "opciones": {"A": "Lanzar desde la mitad de la cancha.", "B": "Pasar de inmediato aunque tu compañero esté marcado.", "C": "Avanzar hacia el aro, porque el defensor no te está marcando.", "D": "Detenerte y esperar a los demás."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué ocupar bien los espacios favorece al ataque?", "opciones": {"A": "Porque la defensa no puede cubrir a todos y quedan líneas de pase abiertas.", "B": "Porque el reglamento lo exige.", "C": "Porque así los atacantes descansan.", "D": "Porque reduce el número de pases."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuál es el mejor lanzamiento?", "opciones": {"A": "El que tiene más probabilidad de entrar.", "B": "El más lejano posible.", "C": "El que lanza el jugador más alto.", "D": "El primero que aparece."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Qué consecuencia tiene pasar bien el balón?", "opciones": {"A": "El partido se vuelve más lento.", "B": "El equipo lanza menos al aro.", "C": "La defensa se mueve más y el equipo pierde menos balones.", "D": "Los defensores descansan más."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea central del primer texto?", "opciones": {"A": "Los pases no influyen en el resultado.", "B": "El baloncesto se gana con el jugador más alto.", "C": "Solo importa lanzar desde lejos.", "D": "El ataque necesita principios colectivos, no solo técnica individual."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "En la defensa individual:", "opciones": {"A": "cada defensor se responsabiliza de un atacante.", "B": "solo defienden tres jugadores.", "C": "cada defensor protege una zona de la cancha.", "D": "los defensores no se mueven."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cómo se ubican los jugadores en la zona 2-3?", "opciones": {"A": "Todos debajo del aro.", "B": "Dos adelante, cerca de la línea de tiros libres, y tres atrás, cerca del aro.", "C": "Tres adelante y dos atrás.", "D": "Uno adelante y cuatro atrás."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Cuál es la debilidad de la defensa en zona, según el texto?", "opciones": {"A": "No permite la ayuda defensiva.", "B": "Deja más libres los lanzamientos desde lejos.", "C": "Exige más condición física que la individual.", "D": "No protege el área cerca del aro."}}, {"n": 11, "seccion": 2, "competencia": "Aplicación", "enunciado": "Tu compañero es superado por su atacante, que va hacia el aro. ¿Qué debes hacer si eres el defensor más cercano?", "opciones": {"A": "Cometer una falta intencional siempre.", "B": "Pedir tiempo muerto.", "C": "Quedarte con tu atacante sin moverte.", "D": "Desplazarte para cerrar el camino al aro (ayuda) y luego recuperar posición."}}, {"n": 12, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, el «rebote defensivo» es:", "opciones": {"A": "una falta del atacante.", "B": "un pase que rebota en el suelo.", "C": "recuperar el balón después de un lanzamiento fallado del rival.", "D": "un tipo de defensa en zona."}}, {"n": 13, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué la comunicación es fundamental en la defensa?", "opciones": {"A": "Porque está prohibido hacer señas.", "B": "Porque el árbitro necesita escucharlos.", "C": "Porque los defensores deben coordinar ayudas, cambios y bloqueos.", "D": "Porque así se distrae al rival."}}, {"n": 14, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Según el segundo texto, ¿por qué una buena defensa «no sirve de nada» sin rebote?", "opciones": {"A": "Porque el rebote vale puntos extra.", "B": "Porque el rival tendría otra oportunidad de anotar.", "C": "Porque la defensa debe cambiar de sistema.", "D": "Porque el árbitro anula la jugada."}}, {"n": 15, "seccion": 3, "competencia": "Literal", "enunciado": "¿Cuándo se realiza el contraataque?", "opciones": {"A": "Al inicio de cada cuarto.", "B": "Solo en los últimos minutos.", "C": "Después de un tiempo muerto.", "D": "Inmediatamente después de recuperar el balón, antes de que el rival se organice."}}, {"n": 16, "seccion": 3, "competencia": "Literal", "enunciado": "En el contraataque, el carril central lo ocupa:", "opciones": {"A": "el entrenador.", "B": "el jugador más alto.", "C": "el defensor rival.", "D": "el jugador que conduce el balón."}}, {"n": 17, "seccion": 3, "competencia": "Aplicación", "enunciado": "El rival defiende en zona y deja libres los lanzamientos lejanos. ¿Qué te recomienda el texto?", "opciones": {"A": "Mover rápido el balón y lanzar de media o larga distancia.", "B": "Usar siempre el contraataque.", "C": "Dejar de lanzar y solo pasar.", "D": "Atacar siempre por el centro de la zona."}}, {"n": 18, "seccion": 3, "competencia": "Aplicación", "enunciado": "Notas que tu marcador es más lento que tú y defienden en individual. ¿Qué decisión es la más adecuada?", "opciones": {"A": "Atacarlo en el uno contra uno.", "B": "Esperar a que se acaben los 24 segundos.", "C": "Lanzar desde la mitad de la cancha.", "D": "Pasar el balón siempre al pívot."}}, {"n": 19, "seccion": 3, "competencia": "Lexical", "enunciado": "«Leer el juego» significa:", "opciones": {"A": "conocer de memoria el reglamento.", "B": "observar lo que hace el rival y tomar la mejor decisión.", "C": "repetir siempre la misma jugada.", "D": "mirar el marcador constantemente."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué conclusión une los tres textos?", "opciones": {"A": "Las jugadas deben ser siempre las mismas.", "B": "La defensa no es importante para ganar.", "C": "El baloncesto depende solo de la estatura.", "D": "En el baloncesto gana quien coordina al equipo y toma buenas decisiones según el rival."}}]}, {"id": "2027-g10-p1-quiz", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 1", "titulo": "Quiz — Fútbol: Reglas de Juego básicas (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Las Reglas de Juego", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Las Reglas de Juego del fútbol las establece la IFAB (International Football Association Board) y las aplica la FIFA en todo el mundo. Cada equipo tiene once jugadores, uno de ellos el guardameta, y un partido no puede comenzar si alguno tiene menos de siete. El partido dura dos tiempos de 45 minutos, más el tiempo que el árbitro añada por pérdidas de tiempo.<br><br>Se concede un tiro penal cuando un jugador comete una falta que se sanciona con tiro libre directo dentro de su propia área penal; el penal se cobra desde 11 metros. Las faltas más leves se sancionan con tiro libre indirecto, en el que el gol solo es válido si el balón toca a otro jugador antes de entrar. La tarjeta amarilla es una amonestación; la roja es una expulsión, y el jugador expulsado no puede ser reemplazado.<br><br>Un jugador está en posición de fuera de juego si, en el momento en que un compañero juega el balón, está en la mitad del campo rival y más cerca de la línea de meta que el balón y que el penúltimo adversario. Estar en esa posición no es una infracción por sí mismo: solo se sanciona si el jugador participa en la jugada. Además, no hay fuera de juego si el jugador recibe directamente de un saque de meta, de banda o de esquina."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué organismo establece las Reglas de Juego del fútbol?", "opciones": {"A": "La IFAB.", "B": "El Comité Olímpico.", "C": "La FIVB.", "D": "La FIBA."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál es el número mínimo de jugadores para iniciar un partido?", "opciones": {"A": "Siete por equipo.", "B": "Once por equipo.", "C": "Cinco por equipo.", "D": "Nueve por equipo."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Desde qué distancia se cobra el tiro penal?", "opciones": {"A": "6 metros.", "B": "11 metros.", "C": "16 metros.", "D": "9 metros."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En un tiro libre «indirecto», el gol es válido solo si:", "opciones": {"A": "se patea con el pie izquierdo.", "B": "se cobra desde fuera del área.", "C": "el balón toca a otro jugador antes de entrar.", "D": "el portero no se mueve."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador recibe tarjeta roja en el minuto 30. ¿Qué ocurre con su equipo?", "opciones": {"A": "Pierde automáticamente el partido.", "B": "Sigue jugando con un jugador menos, porque el expulsado no puede ser reemplazado.", "C": "Puede reemplazarlo con un suplente.", "D": "Debe cobrar un penal en contra."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el árbitro añade tiempo al final de cada tiempo?", "opciones": {"A": "Para que los jugadores descansen.", "B": "Porque el reglamento exige 50 minutos.", "C": "Para compensar el tiempo perdido durante el partido.", "D": "Para que el equipo que pierde pueda empatar."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "Para estar en posición de fuera de juego, el jugador debe estar:", "opciones": {"A": "detrás del balón.", "B": "en la mitad rival, más cerca de la línea de meta que el balón y que el penúltimo adversario.", "C": "en su propia mitad del campo.", "D": "a la misma altura del penúltimo adversario."}}, {"n": 8, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un delantero recibe directamente de un saque de banda estando detrás de todos los defensores. ¿Hay fuera de juego?", "opciones": {"A": "Sí, siempre que esté detrás de los defensores.", "B": "Solo si el árbitro lo considera peligroso.", "C": "Sí, si el balón llega por el aire.", "D": "No, porque desde un saque de banda no hay fuera de juego."}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "Un jugador en posición de fuera de juego que no participa en la jugada:", "opciones": {"A": "no comete infracción.", "B": "recibe tarjeta amarilla.", "C": "debe salir del campo.", "D": "siempre es sancionado."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Para qué sirven, en general, las Reglas de Juego?", "opciones": {"A": "Para que los árbitros decidan el resultado.", "B": "Para que el fútbol sea más lento.", "C": "Para que gane el equipo con más jugadores.", "D": "Para que el partido sea justo, seguro y igual para todos."}}], "modalidad": "Quiz"}, {"id": "2027-g10-p1", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Fútbol: reglamento, táctica y ritmo de juego (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Faltas, sanciones y juego limpio", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "El árbitro sanciona con tiro libre directo las acciones que un jugador comete contra un adversario de manera imprudente, temeraria o con uso de fuerza excesiva: cargar, empujar, golpear, poner una zancadilla o sujetar a un rival, entre otras. También es tiro libre directo tocar el balón deliberadamente con la mano o el brazo, excepto el guardameta dentro de su área. Una acción imprudente se castiga solo con la falta; una temeraria, con tarjeta amarilla; y una con fuerza excesiva, con tarjeta roja.<br><br>El árbitro puede aplicar la «ventaja»: si después de una falta el equipo que la sufrió sigue teniendo una buena opción de ataque, deja continuar el juego en lugar de detenerlo, y puede amonestar al infractor cuando el balón quede fuera de juego. El reglamento busca proteger la integridad física de los jugadores y premiar a quien juega con limpieza. Por eso, actitudes como devolver el balón al rival cuando se detuvo el juego por una lesión no están escritas como obligación, pero hacen parte del espíritu del fútbol."}, {"id": 2, "titulo": "Sistemas tácticos y transiciones", "instruccion": "(Responda las preguntas 8 a 14 con base en el siguiente texto.)", "cuerpo": "Un sistema táctico es la forma en que un equipo distribuye a sus jugadores en el campo. Se nombra con números que van desde la defensa hasta el ataque, sin contar al portero, aunque a veces se escribe el 1 inicial para incluirlo. En el 1-4-4-2 hay cuatro defensas, cuatro mediocampistas y dos delanteros; es un sistema equilibrado. En el 1-4-3-3 hay tres mediocampistas y tres delanteros, lo que favorece el juego por las bandas y la presión en campo rival.<br><br>El fútbol moderno se piensa en cuatro momentos: ataque organizado, defensa organizada y dos transiciones. La transición ataque-defensa ocurre cuando el equipo pierde el balón: los jugadores más cercanos presionan de inmediato para recuperarlo o retrasar al rival, mientras el resto vuelve a su posición. La transición defensa-ataque ocurre al recuperarlo: se busca salir rápido hacia el arco rival antes de que la defensa contraria se organice. Los equipos que dominan las transiciones suelen anotar más goles, porque aprovechan los momentos en que el rival está desordenado."}, {"id": 3, "titulo": "El ritmo del juego y la expresión del jugador", "instruccion": "(Responda las preguntas 15 a 20 con base en el siguiente texto.)", "cuerpo": "Un partido de fútbol tiene ritmo, como una pieza musical. Hay momentos de pausa, en los que el equipo se pasa el balón con calma para ordenarse, y momentos de aceleración, en los que un pase vertical, un cambio de frente o un regate rompen la defensa. Los jugadores inteligentes saben «cambiar el ritmo»: alternan pases cortos y largos, lentos y rápidos, para que el rival no adivine la siguiente acción. El cambio de ritmo también es individual: un delantero que conduce despacio y de repente acelera puede superar a un defensor más rápido que él.<br><br>El fútbol también es expresión corporal y cultural. Las celebraciones, los cantos de la hinchada y los estilos de juego de cada región muestran identidades diferentes. En Colombia, por ejemplo, se suele destacar el juego técnico y de toque. Valorar esas expresiones implica respetar al rival, a los árbitros y a las hinchadas contrarias: la diversidad hace más rica la cultura del fútbol, y la violencia en los estadios la destruye."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuál de estas acciones se sanciona con tiro libre directo?", "opciones": {"A": "Estar en posición de fuera de juego sin participar.", "B": "Poner una zancadilla a un adversario de manera imprudente.", "C": "Celebrar un gol con el público.", "D": "Pedir el balón en voz alta."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Una acción temeraria contra un rival se sanciona con:", "opciones": {"A": "saque de banda.", "B": "tarjeta roja siempre.", "C": "tiro libre directo y tarjeta amarilla.", "D": "solo tiro libre indirecto."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, aplicar la «ventaja» significa:", "opciones": {"A": "dejar seguir el juego si el equipo que sufrió la falta tiene una buena opción de ataque.", "B": "permitir que un equipo tenga un jugador más.", "C": "dar un penal al equipo que va perdiendo.", "D": "añadir tiempo al final del partido."}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un defensor golpea a un rival con fuerza excesiva en una disputa. ¿Qué debe hacer el árbitro?", "opciones": {"A": "Sancionar tiro libre indirecto.", "B": "Sancionar tiro libre directo y mostrar tarjeta roja.", "C": "Dejar seguir el juego sin sanción.", "D": "Mostrar solo tarjeta amarilla."}}, {"n": 5, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Cuál es el propósito principal del reglamento sobre faltas?", "opciones": {"A": "Proteger la integridad física de los jugadores y premiar el juego limpio.", "B": "Aumentar el número de tarjetas.", "C": "Hacer que los partidos tengan menos goles.", "D": "Favorecer a los equipos locales."}}, {"n": 6, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Devolver el balón al rival después de detener el juego por una lesión es un ejemplo de:", "opciones": {"A": "una regla obligatoria de la IFAB.", "B": "una estrategia para ganar tiempo.", "C": "juego limpio, aunque no sea una obligación del reglamento.", "D": "una falta que se sanciona con tarjeta."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué caso un jugador puede tocar el balón con la mano sin cometer falta?", "opciones": {"A": "En cualquier saque de esquina.", "B": "Cuando es el capitán.", "C": "Cuando es el guardameta dentro de su propia área.", "D": "Cuando el balón viene muy rápido."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "En el sistema 1-4-4-2, ¿cuántos delanteros hay?", "opciones": {"A": "Dos.", "B": "Uno.", "C": "Tres.", "D": "Cuatro."}}, {"n": 9, "seccion": 2, "competencia": "Lexical", "enunciado": "Un «sistema táctico» es:", "opciones": {"A": "el uniforme de cada equipo.", "B": "el reglamento oficial del fútbol.", "C": "la forma en que un equipo distribuye a sus jugadores en el campo.", "D": "el entrenamiento físico del equipo."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué el 1-4-3-3 favorece el juego por las bandas?", "opciones": {"A": "Porque tiene cinco defensas.", "B": "Porque el portero juega adelantado.", "C": "Porque no tiene mediocampistas.", "D": "Porque tiene tres delanteros, que pueden abrirse hacia los costados."}}, {"n": 11, "seccion": 2, "competencia": "Literal", "enunciado": "La transición ataque-defensa ocurre cuando el equipo:", "opciones": {"A": "recupera el balón.", "B": "cobra un tiro libre.", "C": "hace un cambio de jugador.", "D": "pierde el balón."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Tu equipo acaba de recuperar el balón y el rival tiene a varios jugadores adelantados. ¿Qué es lo más conveniente según el texto?", "opciones": {"A": "Sacar el balón por la banda.", "B": "Pasar el balón hacia atrás y esperar.", "C": "Detener el juego para hacer un cambio.", "D": "Salir rápido hacia el arco rival antes de que se organice."}}, {"n": 13, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué los equipos que dominan las transiciones suelen anotar más?", "opciones": {"A": "Porque el árbitro los favorece.", "B": "Porque aprovechan los momentos en que el rival está desordenado.", "C": "Porque juegan más minutos.", "D": "Porque tienen más jugadores en el campo."}}, {"n": 14, "seccion": 2, "competencia": "Aplicación", "enunciado": "Tu equipo pierde el balón en campo rival. ¿Qué deben hacer los jugadores más cercanos?", "opciones": {"A": "Detenerse y reclamar al árbitro.", "B": "Esperar a que el rival se equivoque.", "C": "Correr todos hacia su propia área.", "D": "Presionar de inmediato para recuperarlo o retrasar al rival."}}, {"n": 15, "seccion": 3, "competencia": "Lexical", "enunciado": "En el tercer texto, «cambiar el ritmo» significa:", "opciones": {"A": "cambiar la música del estadio.", "B": "cambiar de sistema táctico en cada jugada.", "C": "jugar siempre a la máxima velocidad.", "D": "alternar acciones lentas y rápidas para sorprender al rival."}}, {"n": 16, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Cómo puede un delantero superar a un defensor más rápido que él?", "opciones": {"A": "Esperando a que el defensor se canse.", "B": "Conduciendo despacio y acelerando de repente.", "C": "Pasando siempre hacia atrás.", "D": "Corriendo siempre a la misma velocidad."}}, {"n": 17, "seccion": 3, "competencia": "Literal", "enunciado": "Según el texto, ¿qué ejemplos muestran el fútbol como expresión cultural?", "opciones": {"A": "Las medidas del campo y del balón.", "B": "Las celebraciones, los cantos de la hinchada y los estilos de juego regionales.", "C": "Las tarjetas amarillas y rojas.", "D": "Los sistemas 1-4-4-2 y 1-4-3-3."}}, {"n": 18, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué postura defiende el autor sobre la diversidad en el fútbol?", "opciones": {"A": "La diversidad enriquece la cultura del fútbol y la violencia la destruye.", "B": "Todas las hinchadas deberían animar igual.", "C": "Solo el estilo de toque es válido.", "D": "Las celebraciones deberían prohibirse."}}, {"n": 19, "seccion": 3, "competencia": "Aplicación", "enunciado": "En un partido escolar, un compañero se burla de la forma de celebrar del equipo rival. Según el texto, ¿qué actitud sería la adecuada?", "opciones": {"A": "Respetar la expresión del rival y animar a tu compañero a hacer lo mismo.", "B": "Burlarse también para defender al equipo.", "C": "Pedir al árbitro que expulse al rival.", "D": "Ignorar el partido y retirarse."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué idea integra los tres textos?", "opciones": {"A": "El fútbol depende solo de la técnica individual.", "B": "El reglamento es lo único importante.", "C": "Jugar bien al fútbol combina respetar las reglas, organizarse tácticamente y expresarse con respeto.", "D": "La táctica no tiene relación con el ritmo del juego."}}]}, {"id": "2027-g11-p1-quiz", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 1", "titulo": "Quiz — Actividad física y salud (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 15, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "¿Cuánta actividad física necesitamos?", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "La Organización Mundial de la Salud (OMS) recomienda que los niños y adolescentes de 5 a 17 años realicen, en promedio, al menos 60 minutos diarios de actividad física de intensidad moderada a vigorosa, principalmente aeróbica. Además, al menos tres días a la semana deberían incluir actividades vigorosas y ejercicios que fortalezcan músculos y huesos. Para los adultos, la recomendación es de 150 a 300 minutos semanales de actividad moderada, o de 75 a 150 minutos de actividad vigorosa, más ejercicios de fuerza dos o más días por semana.<br><br>La intensidad moderada es aquella en la que la respiración y el pulso se aceleran, pero todavía se puede conversar; caminar a paso rápido o montar en bicicleta suave son ejemplos. En la intensidad vigorosa, como correr o jugar un partido, la respiración es tan agitada que cuesta hablar. La OMS también recomienda reducir el tiempo sedentario, por ejemplo el que se pasa frente a pantallas. La actividad física regular mejora la salud del corazón y los pulmones, fortalece huesos y músculos, ayuda a controlar el peso y favorece el bienestar mental y el rendimiento escolar."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuánta actividad física diaria recomienda la OMS para adolescentes de 5 a 17 años?", "opciones": {"A": "Dos horas diarias de intensidad vigorosa.", "B": "Al menos 60 minutos en promedio, de intensidad moderada a vigorosa.", "C": "Una hora a la semana.", "D": "Al menos 20 minutos de intensidad suave."}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos días a la semana deberían incluir actividades de fortalecimiento muscular y óseo los adolescentes?", "opciones": {"A": "Al menos tres.", "B": "Ninguno, solo actividad aeróbica.", "C": "Los siete días obligatoriamente.", "D": "Al menos uno."}}, {"n": 3, "seccion": 1, "competencia": "Lexical", "enunciado": "Según el texto, en una actividad de intensidad «moderada»:", "opciones": {"A": "es imposible hablar.", "B": "no se acelera el pulso.", "C": "solo se mueven los brazos.", "D": "la respiración se acelera, pero todavía se puede conversar."}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Cuál de estas actividades es vigorosa?", "opciones": {"A": "Correr o jugar un partido de fútbol.", "B": "Estar sentado leyendo.", "C": "Caminar despacio por el parque.", "D": "Estirarse suavemente."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál es la recomendación semanal de actividad moderada para adultos?", "opciones": {"A": "No hay recomendación para adultos.", "B": "De 150 a 300 minutos.", "C": "De 30 a 60 minutos.", "D": "De 500 a 600 minutos."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué la OMS recomienda reducir el tiempo frente a pantallas?", "opciones": {"A": "Porque es una regla del colegio.", "B": "Porque es tiempo sedentario que afecta la salud.", "C": "Porque así se estudia más.", "D": "Porque las pantallas impiden dormir siempre."}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un estudiante camina 20 minutos al colegio y 20 de regreso, y juega 30 minutos en el descanso. ¿Cumple la recomendación diaria?", "opciones": {"A": "No, porque debe hacerlo de una sola vez.", "B": "Sí, pero solo si lo hace los fines de semana.", "C": "Sí, suma 70 minutos si la intensidad es al menos moderada.", "D": "No, porque caminar nunca cuenta."}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuál es un beneficio de la actividad física regular?", "opciones": {"A": "Elimina la necesidad de dormir.", "B": "Reemplaza una alimentación balanceada.", "C": "Solo mejora la apariencia física.", "D": "Favorece el bienestar mental y el rendimiento escolar."}}, {"n": 9, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «sedentario» se refiere a:", "opciones": {"A": "hacer ejercicio sentado.", "B": "vivir en una zona rural.", "C": "pasar mucho tiempo sentado o con muy poco movimiento.", "D": "entrenar de forma vigorosa."}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la mejor conclusión del texto?", "opciones": {"A": "Moverse con regularidad y a la intensidad adecuada es una necesidad para la salud.", "B": "Basta con hacer ejercicio un día al mes.", "C": "Solo los deportistas necesitan actividad física.", "D": "La actividad física es útil únicamente para bajar de peso."}}], "modalidad": "Quiz"}, {"id": "2027-g11-p1", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Atletismo y plan personal de entrenamiento (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 35, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Los principios del entrenamiento", "instruccion": "(Responda las preguntas 1 a 7 con base en el siguiente texto.)", "cuerpo": "Entrenar no es hacer ejercicio sin orden: es aplicar principios que permiten mejorar sin lesionarse. El principio de sobrecarga progresiva indica que el cuerpo solo mejora si recibe estímulos un poco mayores a los que está acostumbrado; por eso la carga (tiempo, distancia, velocidad o peso) se aumenta de forma gradual, no de golpe. El principio de especificidad dice que el cuerpo se adapta a lo que se entrena: quien quiere mejorar en una carrera de 5 kilómetros debe correr distancias largas, no solo levantar pesas.<br><br>El principio de individualidad recuerda que cada persona responde distinto al mismo entrenamiento, según su edad, su experiencia y su estado físico. El principio de recuperación señala que el cuerpo se fortalece durante el descanso: sin dormir bien, hidratarse y alimentarse, el entrenamiento produce fatiga en lugar de mejoras. Finalmente, el principio de continuidad advierte que los beneficios se pierden si se abandona la práctica durante semanas; es mejor entrenar tres veces por semana todo el año que siete veces durante un mes y luego dejarlo."}, {"id": 2, "titulo": "La sesión y la frecuencia cardiaca", "instruccion": "(Responda las preguntas 8 a 13 con base en el siguiente texto.)", "cuerpo": "Una sesión de entrenamiento tiene tres partes. El calentamiento (10 a 15 minutos) eleva poco a poco la temperatura del cuerpo y la frecuencia cardiaca, con trote suave, movilidad articular y ejercicios de técnica de carrera. La parte principal desarrolla el objetivo del día: por ejemplo, carrera continua, series de velocidad o saltos. La vuelta a la calma (5 a 10 minutos) baja la intensidad con trote suave, caminata y estiramientos.<br><br>La frecuencia cardiaca (FC) es el número de latidos del corazón por minuto y sirve para controlar la intensidad. Una fórmula sencilla para estimar la frecuencia cardiaca máxima es restar la edad a 220: un estudiante de 16 años tendría una FC máxima aproximada de 204 latidos por minuto. Para mejorar la resistencia aeróbica se recomienda trabajar entre el 60 % y el 80 % de esa frecuencia máxima. El pulso se puede tomar en la muñeca o en el cuello, contando los latidos durante 15 segundos y multiplicando por cuatro. Esta fórmula es una estimación: la percepción del esfuerzo y la orientación del docente también son importantes."}, {"id": 3, "titulo": "Del test al plan personal", "instruccion": "(Responda las preguntas 14 a 20 con base en el siguiente texto.)", "cuerpo": "Para diseñar un plan, primero hay que saber de dónde se parte. El test de Cooper consiste en correr la mayor distancia posible en 12 minutos y permite estimar la resistencia aeróbica. Con ese resultado, cada estudiante se plantea una meta. Una buena meta es específica, medible, alcanzable, relevante y con un tiempo definido: por ejemplo, «aumentar 200 metros mi resultado en el test de Cooper en ocho semanas», y no simplemente «estar en forma».<br><br>Un plan sencillo para un estudiante que empieza puede incluir tres sesiones por semana en días no consecutivos, con 20 a 30 minutos de carrera continua a intensidad moderada, y aumentar el tiempo de carrera de forma gradual cada semana. Es útil registrar cada sesión: fecha, duración, sensación de esfuerzo y frecuencia cardiaca. Al final del periodo, se repite el test para comparar. Integrar la actividad física al proyecto de vida significa que no depende de una nota ni de un uniforme: es una decisión personal que acompaña a la persona después del colegio."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Lexical", "enunciado": "El principio de «sobrecarga progresiva» indica que:", "opciones": {"A": "la carga del entrenamiento debe aumentar de forma gradual.", "B": "el descanso no es necesario.", "C": "todas las personas deben entrenar igual.", "D": "hay que entrenar siempre con el máximo peso posible."}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "Una estudiante quiere mejorar su tiempo en una carrera de 5 km. Según el principio de especificidad, debería:", "opciones": {"A": "incluir carreras de distancias largas en su entrenamiento.", "B": "entrenar solo la flexibilidad.", "C": "practicar únicamente saltos.", "D": "hacer solo ejercicios de pesas."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuándo se fortalece el cuerpo?", "opciones": {"A": "Únicamente en competencias.", "B": "Cuando se entrena sin descanso.", "C": "Solo durante el entrenamiento más intenso.", "D": "Durante el descanso, con sueño, hidratación y alimentación adecuados."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué dos compañeros con el mismo plan pueden obtener resultados distintos?", "opciones": {"A": "Porque uno de ellos hizo trampa.", "B": "Porque el principio de especificidad no funciona.", "C": "Por el principio de individualidad: cada persona responde diferente.", "D": "Porque el plan estaba mal escrito."}}, {"n": 5, "seccion": 1, "competencia": "Aplicación", "enunciado": "¿Qué opción respeta mejor el principio de continuidad?", "opciones": {"A": "Entrenar siete veces por semana un mes y luego descansar seis meses.", "B": "Entrenar tres veces por semana durante todo el año.", "C": "Entrenar un día muy fuerte cada dos meses.", "D": "Entrenar solo antes de los exámenes de Educación Física."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Qué puede pasar si se entrena mucho sin recuperación adecuada?", "opciones": {"A": "Se elimina el riesgo de lesiones.", "B": "Se mejora el doble de rápido.", "C": "Se acumula fatiga en lugar de lograr mejoras.", "D": "No ocurre nada, el descanso es opcional."}}, {"n": 7, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la tesis del primer texto?", "opciones": {"A": "Solo los atletas profesionales deben entrenar con principios.", "B": "Entrenar bien requiere aplicar principios para mejorar sin lesionarse.", "C": "Cualquier ejercicio sin orden produce los mismos resultados.", "D": "El descanso es una pérdida de tiempo."}}, {"n": 8, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuáles son las tres partes de una sesión de entrenamiento?", "opciones": {"A": "Estiramiento, competencia y descanso.", "B": "Trote, velocidad y fuerza.", "C": "Inicio, evaluación y premiación.", "D": "Calentamiento, parte principal y vuelta a la calma."}}, {"n": 9, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál es la FC máxima estimada de un estudiante de 16 años según la fórmula del texto?", "opciones": {"A": "204 latidos por minuto.", "B": "220 latidos por minuto.", "C": "236 latidos por minuto.", "D": "180 latidos por minuto."}}, {"n": 10, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un estudiante de 17 años quiere entrenar resistencia aeróbica entre el 60 % y el 80 % de su FC máxima. ¿Cuál es el rango aproximado?", "opciones": {"A": "Entre 100 y 120 latidos por minuto.", "B": "Entre 60 y 80 latidos por minuto.", "C": "Entre 122 y 162 latidos por minuto.", "D": "Entre 170 y 203 latidos por minuto."}}, {"n": 11, "seccion": 2, "competencia": "Aplicación", "enunciado": "Contaste 35 latidos en 15 segundos. ¿Cuál es tu frecuencia cardiaca?", "opciones": {"A": "105 latidos por minuto.", "B": "35 latidos por minuto.", "C": "70 latidos por minuto.", "D": "140 latidos por minuto."}}, {"n": 12, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Para qué sirve la vuelta a la calma?", "opciones": {"A": "Para medir el resultado del test de Cooper.", "B": "Para bajar la intensidad gradualmente después de la parte principal.", "C": "Para reemplazar el calentamiento.", "D": "Para aumentar al máximo la frecuencia cardiaca."}}, {"n": 13, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué el texto aclara que la fórmula 220 menos la edad es «una estimación»?", "opciones": {"A": "Porque la fórmula está prohibida en los colegios.", "B": "Porque la frecuencia cardiaca no tiene relación con la intensidad.", "C": "Porque cada persona es diferente y también hay que considerar la percepción del esfuerzo.", "D": "Porque solo sirve para adultos mayores."}}, {"n": 14, "seccion": 3, "competencia": "Literal", "enunciado": "¿En qué consiste el test de Cooper?", "opciones": {"A": "En correr 100 metros lo más rápido posible.", "B": "En caminar durante una hora.", "C": "En saltar la mayor distancia desde parado.", "D": "En correr la mayor distancia posible en 12 minutos."}}, {"n": 15, "seccion": 3, "competencia": "Aplicación", "enunciado": "¿Cuál de estas metas cumple las características descritas en el texto?", "opciones": {"A": "Correr mucho más.", "B": "Ser el mejor del salón.", "C": "Estar en forma este año.", "D": "Aumentar 200 metros mi resultado del test de Cooper en ocho semanas."}}, {"n": 16, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Por qué el plan propone sesiones en días no consecutivos?", "opciones": {"A": "Porque el test de Cooper se hace cada dos días.", "B": "Para permitir la recuperación entre sesiones.", "C": "Porque está prohibido correr dos días seguidos.", "D": "Para que el plan dure menos semanas."}}, {"n": 17, "seccion": 3, "competencia": "Literal", "enunciado": "¿Qué datos se recomienda registrar en cada sesión?", "opciones": {"A": "Fecha, duración, sensación de esfuerzo y frecuencia cardiaca.", "B": "Únicamente la nota obtenida.", "C": "Solo el nombre del compañero de entrenamiento.", "D": "El clima y la ropa usada."}}, {"n": 18, "seccion": 3, "competencia": "Inferencial", "enunciado": "¿Para qué se repite el test al final del periodo?", "opciones": {"A": "Para calcular la FC máxima.", "B": "Para comparar el resultado con el inicial y valorar el progreso.", "C": "Para cambiar de deporte.", "D": "Para reemplazar el registro de sesiones."}}, {"n": 19, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Según el texto, integrar la actividad física al proyecto de vida significa que:", "opciones": {"A": "termina al graduarse.", "B": "solo se practica con uniforme.", "C": "es una decisión personal que continúa después del colegio.", "D": "depende de la nota de Educación Física."}}, {"n": 20, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Qué relación hay entre los tres textos?", "opciones": {"A": "Los principios, el control de la intensidad y las metas permiten construir un plan personal de entrenamiento.", "B": "Los tres afirman que el descanso no es necesario.", "C": "Los tres explican la historia del atletismo.", "D": "Los tres tratan solo sobre la frecuencia cardiaca."}}]}, {"id": "2027-g10-p2-quiz", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 2", "titulo": "Quiz — Mitos y realidades de la vida saludable (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Lo que se dice en el colegio", "instruccion": "(Responda las preguntas 1 a 6 con base en el siguiente texto y en los recursos de Hábitos de vida saludables.)", "cuerpo": "En una encuesta rápida entre estudiantes de la media aparecieron varias frases que circulan en los descansos, en las redes sociales y hasta en el gimnasio. Algunas tienen respaldo científico y otras son mitos: creencias muy repetidas que no coinciden con lo que dicen los organismos de salud.<br><br>Para separar unas de otras sirve consultar fuentes confiables, como la Organización Mundial de la Salud (OMS) o la Academia Americana de Pediatría (AAP), que revisan la evidencia antes de dar una recomendación. En este quiz encontrarás seis de esas frases. Para cada una, elige la opción que la describe correctamente: si es un mito o una realidad, y por qué."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Aplicación", "enunciado": "«Las bebidas energizantes mejoran el rendimiento deportivo». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: la cafeína que contienen es necesaria para cualquier entrenamiento.", "B": "Realidad: reemplazan el agua y reponen todo lo que se pierde al sudar.", "C": "Mito: aportan cafeína y azúcares, no se recomiendan en adolescentes y, para la mayoría de las sesiones, basta con agua.", "D": "Mito: solo funcionan si se toman frías y antes del calentamiento."}}, {"n": 2, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Hacer abdominales elimina la grasa del abdomen». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: no se pierde grasa localizada ejercitando una sola zona; las abdominales fortalecen el músculo.", "B": "Realidad: cada abdominal quema la grasa que está justo encima del músculo trabajado.", "C": "Realidad: basta con hacer cien abdominales diarias para reducir la cintura.", "D": "Mito: las abdominales no tienen ningún efecto sobre el cuerpo."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "«Un adolescente debería acumular en promedio 60 minutos diarios de actividad física moderada a vigorosa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: la OMS recomienda solo 60 minutos a la semana.", "B": "Mito: esa recomendación es únicamente para deportistas de competencia.", "C": "Realidad, pero solo si los 60 minutos se hacen en una sola sesión sin pausas.", "D": "Realidad: es la recomendación de la OMS (2020) para niños y adolescentes de 5 a 17 años."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "«Sudar más significa que quemaste más grasa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el sudor es grasa que sale del cuerpo en forma líquida.", "B": "Mito: el sudor sirve para regular la temperatura del cuerpo; sudar más no indica que se haya quemado más grasa.", "C": "Realidad: por eso conviene entrenar con ropa plástica o muy abrigada.", "D": "Mito: sudar es una señal de que el ejercicio fue inútil."}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Dormir poco no afecta el rendimiento físico ni el académico». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el cuerpo se adapta a dormir cuatro o cinco horas sin consecuencias.", "B": "Realidad: el sueño solo es importante en la infancia.", "C": "Mito: dormir poco afecta la concentración, la memoria y el rendimiento; los adolescentes necesitan de 8 a 10 horas.", "D": "Mito: dormir poco solo afecta a quienes practican deporte."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "«La hidratación solo importa en los deportes de competencia». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: en una clase de Educación Física no se pierde agua.", "B": "Realidad: solo hay que beber cuando aparece una sed muy intensa.", "C": "Mito: hidratarse solo es necesario en días de mucho calor.", "D": "Mito: hay que hidratarse antes, durante y después de cualquier actividad física, incluida la clase y el juego."}}]}, {"id": "2027-g10-p3-quiz", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 3", "titulo": "Quiz — Chequeo saludable: actividad física, nutrición, hidratación y descanso (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 12, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Cuatro hábitos que sostienen la salud", "instruccion": "(Responda las preguntas 1 a 8 con base en el siguiente texto.)", "cuerpo": "<b>Actividad física.</b> Según las directrices de la Organización Mundial de la Salud (OMS, 2020), los niños y adolescentes de 5 a 17 años deberían acumular en promedio 60 minutos diarios de actividad física de intensidad moderada a vigorosa, en su mayoría aeróbica. Al menos tres días por semana conviene incluir actividades vigorosas y ejercicios que fortalezcan músculos y huesos. También recomienda limitar el tiempo sedentario, en especial el que se pasa frente a pantallas por diversión.<br><br><b>Nutrición.</b> La OMS señala que una alimentación saludable incluye frutas, verduras, legumbres y cereales integrales. A partir de los 10 años se recomienda consumir al menos 400 gramos de frutas y verduras al día. Los azúcares libres —los que se añaden a bebidas y alimentos, y los de jugos y mieles— deberían ser menos del 10 % de la energía diaria, e idealmente menos del 5 %. También aconseja reducir la sal.<br><br><b>Hidratación.</b> La Academia Americana de Pediatría (AAP) explica que el agua es la mejor bebida para la mayoría de las actividades físicas de niños y adolescentes. Las bebidas deportivas, que aportan azúcares y electrolitos, solo pueden ayudar en actividades vigorosas y prolongadas. Las bebidas energizantes son otro producto: contienen cafeína y otros estimulantes, y los niños y adolescentes no deberían consumirlas.<br><br><b>Descanso.</b> La AAP apoya las pautas de la Academia Estadounidense de Medicina del Sueño: los adolescentes de 13 a 18 años necesitan de 8 a 10 horas de sueño en cada periodo de 24 horas. Dormir lo suficiente se relaciona con mejor memoria, comportamiento, rendimiento académico y salud mental; dormir poco se asocia con dificultades para concentrarse, dolores de cabeza y otros problemas de salud."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuánta actividad física recomienda la OMS a los adolescentes?", "opciones": {"A": "60 minutos a la semana, solo en la clase de Educación Física.", "B": "En promedio 60 minutos diarios de intensidad moderada a vigorosa.", "C": "Dos horas diarias de ejercicio de fuerza.", "D": "30 minutos de caminata suave, tres veces por semana."}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "Camila juega videojuegos cuatro horas al día y solo se mueve en la clase de Educación Física. Según la OMS, ¿qué le convendría cambiar primero?", "opciones": {"A": "Reducir el tiempo frente a la pantalla y sumar actividad física moderada a vigorosa casi todos los días.", "B": "Nada, porque la clase de Educación Física ya cubre lo recomendado.", "C": "Hacer ejercicio solo el fin de semana durante varias horas seguidas.", "D": "Cambiar los videojuegos por series de televisión."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué cantidad mínima de frutas y verduras al día recomienda la OMS a partir de los 10 años?", "opciones": {"A": "100 gramos.", "B": "200 gramos.", "C": "400 gramos.", "D": "Una sola fruta a la semana."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la expresión «azúcares libres» se refiere a:", "opciones": {"A": "el azúcar que contienen las frutas enteras y las verduras.", "B": "los alimentos que no tienen ningún tipo de azúcar.", "C": "los carbohidratos de los cereales integrales.", "D": "los azúcares que se añaden a bebidas y alimentos, y los de jugos y mieles."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "Según la AAP, ¿cuál es la mejor bebida para la mayoría de las actividades físicas de los adolescentes?", "opciones": {"A": "Una bebida energizante.", "B": "El agua.", "C": "Una gaseosa.", "D": "Una bebida deportiva en cualquier sesión."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto distingue entre bebidas deportivas y bebidas energizantes?", "opciones": {"A": "Porque las energizantes contienen cafeína y estimulantes que los adolescentes no deberían consumir.", "B": "Porque las energizantes hidratan mejor que el agua.", "C": "Porque las deportivas están prohibidas para menores de edad.", "D": "Porque ambas son iguales y solo cambia el sabor."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas horas de sueño necesitan los adolescentes de 13 a 18 años?", "opciones": {"A": "De 5 a 6 horas.", "B": "De 6 a 7 horas.", "C": "De 11 a 14 horas.", "D": "De 8 a 10 horas."}}, {"n": 8, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Andrés se acuesta a la 1:00 a. m. para terminar tareas y se levanta a las 5:30 a. m. ¿Qué conclusión es coherente con el texto?", "opciones": {"A": "Su horario es adecuado porque aprovecha mejor el tiempo.", "B": "Dormir poco solo le afectará si practica deporte.", "C": "Duerme menos de lo recomendado, lo que puede afectar su concentración, su memoria y su rendimiento.", "D": "Puede recuperar todo el sueño perdido durmiendo una siesta corta."}}]}, {"id": "2027-g11-p2-quiz", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 2", "titulo": "Quiz — Mitos y realidades de la vida saludable (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Lo que se dice en el colegio", "instruccion": "(Responda las preguntas 1 a 6 con base en el siguiente texto y en los recursos de Hábitos de vida saludables.)", "cuerpo": "En una encuesta rápida entre estudiantes de la media aparecieron varias frases que circulan en los descansos, en las redes sociales y hasta en el gimnasio. Algunas tienen respaldo científico y otras son mitos: creencias muy repetidas que no coinciden con lo que dicen los organismos de salud.<br><br>Para separar unas de otras sirve consultar fuentes confiables, como la Organización Mundial de la Salud (OMS) o la Academia Americana de Pediatría (AAP), que revisan la evidencia antes de dar una recomendación. En este quiz encontrarás seis de esas frases. Para cada una, elige la opción que la describe correctamente: si es un mito o una realidad, y por qué."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Aplicación", "enunciado": "«Las bebidas energizantes mejoran el rendimiento deportivo». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: la cafeína que contienen es necesaria para cualquier entrenamiento.", "B": "Realidad: reemplazan el agua y reponen todo lo que se pierde al sudar.", "C": "Mito: aportan cafeína y azúcares, no se recomiendan en adolescentes y, para la mayoría de las sesiones, basta con agua.", "D": "Mito: solo funcionan si se toman frías y antes del calentamiento."}}, {"n": 2, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Hacer abdominales elimina la grasa del abdomen». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: no se pierde grasa localizada ejercitando una sola zona; las abdominales fortalecen el músculo.", "B": "Realidad: cada abdominal quema la grasa que está justo encima del músculo trabajado.", "C": "Realidad: basta con hacer cien abdominales diarias para reducir la cintura.", "D": "Mito: las abdominales no tienen ningún efecto sobre el cuerpo."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "«Un adolescente debería acumular en promedio 60 minutos diarios de actividad física moderada a vigorosa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Mito: la OMS recomienda solo 60 minutos a la semana.", "B": "Mito: esa recomendación es únicamente para deportistas de competencia.", "C": "Realidad, pero solo si los 60 minutos se hacen en una sola sesión sin pausas.", "D": "Realidad: es la recomendación de la OMS (2020) para niños y adolescentes de 5 a 17 años."}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "«Sudar más significa que quemaste más grasa». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el sudor es grasa que sale del cuerpo en forma líquida.", "B": "Mito: el sudor sirve para regular la temperatura del cuerpo; sudar más no indica que se haya quemado más grasa.", "C": "Realidad: por eso conviene entrenar con ropa plástica o muy abrigada.", "D": "Mito: sudar es una señal de que el ejercicio fue inútil."}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "«Dormir poco no afecta el rendimiento físico ni el académico». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: el cuerpo se adapta a dormir cuatro o cinco horas sin consecuencias.", "B": "Realidad: el sueño solo es importante en la infancia.", "C": "Mito: dormir poco afecta la concentración, la memoria y el rendimiento; los adolescentes necesitan de 8 a 10 horas.", "D": "Mito: dormir poco solo afecta a quienes practican deporte."}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "«La hidratación solo importa en los deportes de competencia». ¿Cuál de las siguientes opciones describe correctamente esta afirmación?", "opciones": {"A": "Realidad: en una clase de Educación Física no se pierde agua.", "B": "Realidad: solo hay que beber cuando aparece una sed muy intensa.", "C": "Mito: hidratarse solo es necesario en días de mucho calor.", "D": "Mito: hay que hidratarse antes, durante y después de cualquier actividad física, incluida la clase y el juego."}}]}, {"id": "2027-g11-p3-quiz", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 3", "titulo": "Quiz — Chequeo saludable: actividad física, nutrición, hidratación y descanso (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 12, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [{"id": 1, "titulo": "Cuatro hábitos que sostienen la salud", "instruccion": "(Responda las preguntas 1 a 8 con base en el siguiente texto.)", "cuerpo": "<b>Actividad física.</b> Según las directrices de la Organización Mundial de la Salud (OMS, 2020), los niños y adolescentes de 5 a 17 años deberían acumular en promedio 60 minutos diarios de actividad física de intensidad moderada a vigorosa, en su mayoría aeróbica. Al menos tres días por semana conviene incluir actividades vigorosas y ejercicios que fortalezcan músculos y huesos. También recomienda limitar el tiempo sedentario, en especial el que se pasa frente a pantallas por diversión.<br><br><b>Nutrición.</b> La OMS señala que una alimentación saludable incluye frutas, verduras, legumbres y cereales integrales. A partir de los 10 años se recomienda consumir al menos 400 gramos de frutas y verduras al día. Los azúcares libres —los que se añaden a bebidas y alimentos, y los de jugos y mieles— deberían ser menos del 10 % de la energía diaria, e idealmente menos del 5 %. También aconseja reducir la sal.<br><br><b>Hidratación.</b> La Academia Americana de Pediatría (AAP) explica que el agua es la mejor bebida para la mayoría de las actividades físicas de niños y adolescentes. Las bebidas deportivas, que aportan azúcares y electrolitos, solo pueden ayudar en actividades vigorosas y prolongadas. Las bebidas energizantes son otro producto: contienen cafeína y otros estimulantes, y los niños y adolescentes no deberían consumirlas.<br><br><b>Descanso.</b> La AAP apoya las pautas de la Academia Estadounidense de Medicina del Sueño: los adolescentes de 13 a 18 años necesitan de 8 a 10 horas de sueño en cada periodo de 24 horas. Dormir lo suficiente se relaciona con mejor memoria, comportamiento, rendimiento académico y salud mental; dormir poco se asocia con dificultades para concentrarse, dolores de cabeza y otros problemas de salud."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cuánta actividad física recomienda la OMS a los adolescentes?", "opciones": {"A": "60 minutos a la semana, solo en la clase de Educación Física.", "B": "En promedio 60 minutos diarios de intensidad moderada a vigorosa.", "C": "Dos horas diarias de ejercicio de fuerza.", "D": "30 minutos de caminata suave, tres veces por semana."}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "Camila juega videojuegos cuatro horas al día y solo se mueve en la clase de Educación Física. Según la OMS, ¿qué le convendría cambiar primero?", "opciones": {"A": "Reducir el tiempo frente a la pantalla y sumar actividad física moderada a vigorosa casi todos los días.", "B": "Nada, porque la clase de Educación Física ya cubre lo recomendado.", "C": "Hacer ejercicio solo el fin de semana durante varias horas seguidas.", "D": "Cambiar los videojuegos por series de televisión."}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué cantidad mínima de frutas y verduras al día recomienda la OMS a partir de los 10 años?", "opciones": {"A": "100 gramos.", "B": "200 gramos.", "C": "400 gramos.", "D": "Una sola fruta a la semana."}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, la expresión «azúcares libres» se refiere a:", "opciones": {"A": "el azúcar que contienen las frutas enteras y las verduras.", "B": "los alimentos que no tienen ningún tipo de azúcar.", "C": "los carbohidratos de los cereales integrales.", "D": "los azúcares que se añaden a bebidas y alimentos, y los de jugos y mieles."}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "Según la AAP, ¿cuál es la mejor bebida para la mayoría de las actividades físicas de los adolescentes?", "opciones": {"A": "Una bebida energizante.", "B": "El agua.", "C": "Una gaseosa.", "D": "Una bebida deportiva en cualquier sesión."}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto distingue entre bebidas deportivas y bebidas energizantes?", "opciones": {"A": "Porque las energizantes contienen cafeína y estimulantes que los adolescentes no deberían consumir.", "B": "Porque las energizantes hidratan mejor que el agua.", "C": "Porque las deportivas están prohibidas para menores de edad.", "D": "Porque ambas son iguales y solo cambia el sabor."}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas horas de sueño necesitan los adolescentes de 13 a 18 años?", "opciones": {"A": "De 5 a 6 horas.", "B": "De 6 a 7 horas.", "C": "De 11 a 14 horas.", "D": "De 8 a 10 horas."}}, {"n": 8, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Andrés se acuesta a la 1:00 a. m. para terminar tareas y se levanta a las 5:30 a. m. ¿Qué conclusión es coherente con el texto?", "opciones": {"A": "Su horario es adecuado porque aprovecha mejor el tiempo.", "B": "Dormir poco solo le afectará si practica deporte.", "C": "Duerme menos de lo recomendado, lo que puede afectar su concentración, su memoria y su rendimiento.", "D": "Puede recuperar todo el sueño perdido durmiendo una siesta corta."}}]}, {"id": "2027-g6-p2-quiz1", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Salidas y carreras (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál de estas pruebas es de velocidad?", "opciones": {"A": "100 metros planos", "B": "Maratón", "C": "5.000 metros", "D": "Marcha de 20 kilómetros"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos metros mide una vuelta completa a una pista de atletismo estándar?", "opciones": {"A": "100 metros", "B": "200 metros", "C": "400 metros", "D": "800 metros"}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "Tras la voz «listos», tu compañero se mueve antes del disparo. ¿Cómo se llama esa falta?", "opciones": {"A": "Salida nula", "B": "Falsa salida", "C": "Relevo fallido", "D": "Invasión de carril"}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué capacidad física se trabaja más en una carrera de 3.000 metros?", "opciones": {"A": "Resistencia", "B": "Fuerza máxima", "C": "Flexibilidad", "D": "Equilibrio"}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué es importante hidratarse antes y después de correr?", "opciones": {"A": "Porque el agua da más fuerza en las piernas de inmediato", "B": "Porque así no hace falta calentar", "C": "Porque el reglamento lo exige", "D": "Porque se pierden líquidos con el sudor y reponerlos ayuda al rendimiento y a la recuperación"}}]}, {"id": "2027-g6-p2-quiz2", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Relevos y salto largo (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué objeto se pasan los atletas en un relevo?", "opciones": {"A": "La jabalina", "B": "El testigo", "C": "El listón", "D": "El balón"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál es el orden correcto de las fases del salto largo?", "opciones": {"A": "Carrera, batida, vuelo y caída", "B": "Batida, carrera, caída y vuelo", "C": "Vuelo, carrera, batida y caída", "D": "Caída, vuelo, batida y carrera"}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un relevo se cae el testigo. ¿Qué debe hacer el equipo?", "opciones": {"A": "Abandonar la prueba", "B": "Que lo recoja el juez", "C": "Reiniciar la carrera desde la salida", "D": "Que lo recoja el atleta que lo soltó y continúe"}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para saltar más lejos en salto largo conviene", "opciones": {"A": "frenar antes de la tabla", "B": "caer de pie en el mismo lugar", "C": "llegar a la tabla con buena velocidad y batir con fuerza", "D": "cerrar los ojos al despegar"}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué el foso de arena debe estar rastrillado y sin objetos duros?", "opciones": {"A": "Para evitar lesiones al caer", "B": "Para que la arena se vea ordenada", "C": "Para que los saltos sean más cortos", "D": "Para que el juez mida más rápido"}}]}, {"id": "2027-g6-p2", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 2", "titulo": "Evaluación tipo Saber — Atletismo: carreras, relevos y salto largo (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 25, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "La carrera de velocidad", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "En una carrera de velocidad, como los 100 metros planos, gana quien cruza primero la línea de meta con el torso. Los atletas parten desde una posición baja, apoyando las manos y los pies en los tacos de salida o, en la escuela, directamente en el piso. El juez da tres voces: «a sus puestos», «listos» y el disparo. Si un atleta sale antes del disparo, comete una falsa salida y queda descalificado. Cada corredor debe mantenerse en su propio carril desde la salida hasta la meta, porque invadir el carril del vecino puede significar la descalificación. En los primeros metros el cuerpo va inclinado hacia adelante y los pasos son cortos y potentes; después el tronco se levanta y la zancada se alarga. Los brazos se mueven flexionados, de adelante hacia atrás, sin cruzar el cuerpo. Calentar antes de correr ayuda a evitar lesiones, sobre todo en los músculos de la parte trasera del muslo."}, {"id": 2, "titulo": "Relevos y salto largo", "instruccion": "(Responda las preguntas 11 a 20 con base en el siguiente texto.)", "cuerpo": "En el relevo 4x100, cuatro atletas recorren 100 metros cada uno y se pasan un testigo, un tubo liviano que debe viajar en la mano durante toda la carrera. El pase se hace dentro de la zona de transferencia, un tramo marcado de 20 metros; si el testigo se entrega fuera de esa zona, el equipo es descalificado. Quien recibe empieza a correr un poco antes para llegar a la zona con velocidad y extiende la mano hacia atrás sin mirar. Si el testigo se cae, debe recogerlo el atleta que lo soltó. En el salto largo, la carrera de impulso termina en la tabla de batida, donde el atleta se despega con un solo pie. Si pisa más allá de la tabla, el salto es nulo y no se mide. La marca se mide desde la tabla hasta la huella más cercana que deje cualquier parte del cuerpo en la arena. Cada saltador tiene varios intentos y gana quien logra la mayor distancia válida."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuál es el orden de las voces en la salida de una carrera de velocidad?", "opciones": {"A": "«A sus puestos», «listos» y disparo", "B": "«Listos», «a sus puestos» y disparo", "C": "Disparo, «listos» y «a sus puestos»", "D": "«A sus puestos», disparo y «listos»"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿qué ocurre si un atleta sale antes del disparo?", "opciones": {"A": "Repite la carrera sin ninguna sanción", "B": "Sale de último en la siguiente carrera", "C": "Comete una falsa salida y queda descalificado", "D": "Pierde un punto en la tabla"}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Con qué parte del cuerpo se cruza la meta para ganar?", "opciones": {"A": "Con la cabeza", "B": "Con la punta del pie", "C": "Con el torso", "D": "Con las manos"}}, {"n": 4, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué los primeros pasos son cortos y potentes?", "opciones": {"A": "Para descansar al comienzo de la carrera", "B": "Para que el juez no vea la salida", "C": "Para guardar fuerzas para la meta", "D": "Para vencer la inercia y acelerar el cuerpo desde el reposo"}}, {"n": 5, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «falsa salida» significa", "opciones": {"A": "arrancar antes de la señal de salida", "B": "salir con zapatos inadecuados", "C": "salir por un carril que no corresponde", "D": "salir tarde de los tacos"}}, {"n": 6, "seccion": 1, "competencia": "Aplicación", "enunciado": "A Camila se le cruzan los brazos sobre el pecho al correr. ¿Qué corrección debe aplicar?", "opciones": {"A": "Dejarlos sueltos y colgando", "B": "Moverlos flexionados de adelante hacia atrás, sin cruzar el cuerpo", "C": "Cruzarlos más para tener equilibrio", "D": "Mantenerlos quietos pegados al cuerpo"}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Antes de una carrera de velocidad, ¿qué calentamiento es más adecuado?", "opciones": {"A": "Quedarse sentado para ahorrar energía", "B": "Movilidad de articulaciones, trote suave y ejercicios dinámicos", "C": "Correr a máxima velocidad desde el primer minuto", "D": "Tomar bastante agua y arrancar de inmediato"}}, {"n": 8, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué es importante que cada corredor se mantenga en su carril?", "opciones": {"A": "Para que el que va adelante pueda cerrarles el paso a los demás", "B": "Porque cada carril tiene un premio distinto", "C": "Para que el juez tenga menos trabajo", "D": "Para que la competencia sea justa y no haya choques"}}, {"n": 9, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué se recomienda calentar sobre todo la parte trasera del muslo?", "opciones": {"A": "Porque es el único músculo que se usa al correr", "B": "Porque es un músculo muy exigido al correr y se lesiona con facilidad", "C": "Porque el juez lo revisa antes de la salida", "D": "Porque se estira solo con el calentamiento de los brazos"}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un compañero dice: «En los 100 metros solo importa correr fuerte, la técnica no sirve». Según el texto, su afirmación es", "opciones": {"A": "equivocada, porque la inclinación, la zancada y el movimiento de brazos mejoran el rendimiento", "B": "correcta, porque la técnica solo importa en carreras largas", "C": "correcta, porque solo cuenta la fuerza", "D": "equivocada, porque lo único importante es el calzado"}}, {"n": 11, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuántos atletas forman un relevo 4x100 y cuánto corre cada uno?", "opciones": {"A": "Dos atletas, 200 metros cada uno", "B": "Tres atletas, 133 metros cada uno", "C": "Cuatro atletas, 400 metros cada uno", "D": "Cuatro atletas, 100 metros cada uno"}}, {"n": 12, "seccion": 2, "competencia": "Literal", "enunciado": "¿Dónde debe hacerse el pase del testigo?", "opciones": {"A": "Dentro de la zona de transferencia de 20 metros", "B": "En cualquier punto de la pista", "C": "Solamente sobre la línea de meta", "D": "Antes de que empiece la zona marcada"}}, {"n": 13, "seccion": 2, "competencia": "Literal", "enunciado": "Si el testigo se cae, ¿quién debe recogerlo?", "opciones": {"A": "El atleta que lo soltó", "B": "El juez de pista", "C": "El compañero que iba a recibirlo", "D": "Cualquier integrante del equipo"}}, {"n": 14, "seccion": 2, "competencia": "Literal", "enunciado": "¿Qué es la tabla de batida?", "opciones": {"A": "El lugar donde cae el saltador", "B": "El instrumento con el que se mide el salto", "C": "El lugar donde termina la carrera de impulso y el atleta se despega", "D": "El punto de salida del relevo"}}, {"n": 15, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué quien recibe el testigo empieza a correr antes de que llegue su compañero?", "opciones": {"A": "Para ganarle la carrera a su compañero", "B": "Para guardar fuerzas durante la prueba", "C": "Porque el juez lo exige en cada pase", "D": "Para llegar a la zona con velocidad y no perder tiempo en el pase"}}, {"n": 16, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué la marca se toma desde la huella más cercana a la tabla?", "opciones": {"A": "Porque así los saltos parecen más largos", "B": "Porque solo los pies dejan huella en la arena", "C": "Porque lo decide cada saltador", "D": "Porque debe reflejar la distancia realmente alcanzada, aunque el atleta caiga hacia atrás"}}, {"n": 17, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un equipo entrega el testigo cuando el receptor ya salió de la zona de transferencia. ¿Qué sucede?", "opciones": {"A": "Se repite el pase", "B": "El equipo es descalificado", "C": "Pierde un segundo en el tiempo final", "D": "Continúa sin sanción"}}, {"n": 18, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un saltador pisa más allá de la tabla de batida y cae a 4 metros. ¿Cómo se califica el intento?", "opciones": {"A": "Se mide y se le descuentan 50 centímetros", "B": "Se mide normalmente", "C": "Es nulo y no se mide", "D": "Se repite toda la competencia"}}, {"n": 19, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué el relevo es un buen ejemplo de trabajo en equipo?", "opciones": {"A": "Porque gana siempre el corredor más veloz", "B": "Porque cada atleta compite por separado", "C": "Porque el resultado depende de la coordinación entre todos y no solo de la velocidad individual", "D": "Porque se premia a quien corre más distancia"}}, {"n": 20, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Para un relevo de curso con corredores de distinta velocidad, ¿qué estrategia es más acertada?", "opciones": {"A": "Dejar de practicar y confiar en la suerte", "B": "Practicar los pases en la zona, porque un buen cambio puede ganar más tiempo que correr un poco más rápido", "C": "Hacer correr a todos sin testigo", "D": "Dejar fuera a los más lentos"}}]}, {"id": "2027-g7-p2-quiz1", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Lanzamientos (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "En los lanzamientos del atletismo, ¿qué se mide?", "opciones": {"A": "La altura del implemento", "B": "La distancia alcanzada", "C": "El tiempo de vuelo", "D": "El peso del atleta"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "En el lanzamiento de bala, el atleta debe permanecer", "opciones": {"A": "dentro del círculo hasta que la bala caiga", "B": "fuera del círculo para tomar impulso", "C": "en la zona de caída", "D": "donde el juez le indique cada vez"}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero sale del círculo antes de que la bala caiga. ¿Cómo se califica?", "opciones": {"A": "Como intento válido", "B": "Como un lanzamiento doble", "C": "Como intento nulo", "D": "Como empate"}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué partes del cuerpo aportan más fuerza al lanzar la bala?", "opciones": {"A": "Las piernas y la cadera", "B": "Solo los dedos", "C": "Solo la cabeza", "D": "Los pies sin las piernas"}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué se espera la orden del profesor antes de lanzar?", "opciones": {"A": "Para que el profesor tenga más trabajo", "B": "Para lanzar más lejos", "C": "Porque el reglamento prohíbe lanzar en grupo", "D": "Para cuidar la seguridad de todos los que están cerca"}}]}, {"id": "2027-g7-p2-quiz2", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Saltos (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿En qué prueba se mide la altura superada?", "opciones": {"A": "Salto alto", "B": "Salto largo", "C": "Lanzamiento de bala", "D": "Relevo 4x100"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "La técnica Fosbury flop se usa en", "opciones": {"A": "el salto triple", "B": "la jabalina", "C": "el salto alto", "D": "la carrera de vallas"}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "En el salto triple, después del brinco el atleta ejecuta", "opciones": {"A": "la caída final", "B": "el paso", "C": "la carrera de impulso", "D": "el salto de vallas"}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "En el salto triple la medida se toma hasta", "opciones": {"A": "la huella más lejana", "B": "el borde del foso", "C": "el último paso de la carrera", "D": "la huella más cercana a la tabla de batida"}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué se debe calentar piernas, tobillos y rodillas antes de saltar?", "opciones": {"A": "Porque los saltos exigen mucho a esas articulaciones y calentar previene lesiones", "B": "Porque así se salta con los ojos cerrados", "C": "Porque no hace falta calentar los brazos", "D": "Porque el juez lo revisa"}}]}, {"id": "2027-g7-p2", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 2", "titulo": "Evaluación tipo Saber — Atletismo: lanzamientos y saltos (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 25, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Lanzamientos: bala y jabalina", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "Los lanzamientos del atletismo combinan fuerza y técnica. En el lanzamiento de bala o peso, el atleta no «tira» la bala: la empuja. La sostiene apoyada en el cuello, bajo la mandíbula, y la impulsa con una extensión del brazo, mientras las piernas y la cadera aportan la mayor parte de la fuerza. Todo el lanzamiento se hace dentro de un círculo, y el atleta no puede salir de él hasta que la bala caiga; si sale antes, el intento es nulo. En la jabalina, el implemento se agarra por la empuñadura, se lleva sobre el hombro y se lanza después de una carrera de aproximación. Para que el lanzamiento sea válido, la punta de la jabalina debe tocar el suelo antes que cualquier otra parte. La marca se mide desde la huella más cercana del implemento hasta el borde del círculo o el arco de lanzamiento. En la escuela se usan implementos livianos y solo se lanza cuando nadie está en la zona de caída."}, {"id": 2, "titulo": "Saltos: alto y triple", "instruccion": "(Responda las preguntas 11 a 20 con base en el siguiente texto.)", "cuerpo": "En el salto alto, el atleta debe superar un listón colocado sobre dos soportes sin derribarlo. La técnica más usada se llama Fosbury flop: el saltador pasa de espaldas al listón y cae sobre un colchón. Recibe ese nombre por Dick Fosbury, quien la popularizó en los Juegos Olímpicos de 1968. Cada altura permite tres intentos, y el atleta queda eliminado cuando falla tres intentos seguidos, ya sea en la misma altura o en alturas distintas; un salto válido reinicia la cuenta. Gana quien supera la mayor altura. En el salto triple, el atleta encadena tres saltos después de la carrera: el brinco, que se despega y cae en el mismo pie; el paso, que cae en el pie contrario; y el salto final, que cae con ambos pies en la arena. La medida se toma desde la tabla de batida hasta la huella más cercana. En las dos pruebas, la zona de caída debe ser blanda y estar libre de objetos."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se sostiene la bala antes de lanzarla?", "opciones": {"A": "Sobre la cabeza con las dos manos", "B": "Colgando a un lado del cuerpo", "C": "Apoyada en el cuello, bajo la mandíbula", "D": "Entre la cintura y la cadera"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "En la jabalina, ¿qué debe tocar el suelo primero para que el lanzamiento sea válido?", "opciones": {"A": "La punta", "B": "La empuñadura", "C": "La cola", "D": "Cualquier parte, da igual"}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿De dónde viene la mayor parte de la fuerza en el lanzamiento de bala?", "opciones": {"A": "De las piernas y la cadera", "B": "Solo de la muñeca", "C": "Solo de los hombros", "D": "De la carrera de aproximación"}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "¿Desde dónde se toma la medida de un lanzamiento?", "opciones": {"A": "Desde la huella más lejana hasta la línea de meta", "B": "Desde la huella más cercana del implemento hasta el borde del círculo o el arco", "C": "Desde el lanzador hasta el juez", "D": "Desde el centro del campo hasta la jabalina"}}, {"n": 5, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «implemento» se refiere a", "opciones": {"A": "el objeto que se lanza en la prueba, como la bala o la jabalina", "B": "el traje del atleta", "C": "el círculo de lanzamiento", "D": "el juez que mide"}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Qué quiere decir el texto con «la bala se empuja, no se tira»?", "opciones": {"A": "Que se lanza con un giro de cabeza", "B": "Que el movimiento correcto es una extensión del brazo desde el cuello, apoyada por piernas y cadera", "C": "Que se arroja desde atrás de la espalda", "D": "Que no hace falta usar las piernas"}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Una estudiante lanza la jabalina y esta cae plana, de lado. ¿Cómo se califica el intento?", "opciones": {"A": "Como válido y se mide dos veces", "B": "Como nulo", "C": "Como válido si llegó lejos", "D": "Como una falta del juez"}}, {"n": 8, "seccion": 1, "competencia": "Aplicación", "enunciado": "Antes de lanzar en clase, lo primero que se debe verificar es", "opciones": {"A": "que el público esté cerca para animar", "B": "que el implemento sea el más pesado", "C": "que se pueda lanzar sin calentar", "D": "que no haya nadie en la zona de caída"}}, {"n": 9, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué en la escuela se usan implementos livianos?", "opciones": {"A": "Porque los pesados están prohibidos en todo el mundo", "B": "Porque así todos lanzan igual de lejos", "C": "Porque la técnica no importa en la escuela", "D": "Porque permiten aprender la técnica con seguridad y sin sobrecargar el cuerpo"}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Qué conclusión del texto es más válida?", "opciones": {"A": "Basta con tener mucha fuerza en los brazos", "B": "La técnica solo importa en la jabalina", "C": "El mejor lanzamiento combina fuerza con una técnica coordinada de piernas, cadera y brazo", "D": "La carrera de aproximación es lo único que cuenta"}}, {"n": 11, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cómo se llama la técnica más usada en el salto alto?", "opciones": {"A": "Salto tijera", "B": "Fosbury flop", "C": "Salto de rana", "D": "Remate en suspensión"}}, {"n": 12, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuándo queda eliminado un saltador de altura?", "opciones": {"A": "Cuando falla tres intentos seguidos", "B": "Cuando falla una sola vez", "C": "Cuando falla dos alturas distintas", "D": "Cuando termina el tiempo del juez"}}, {"n": 13, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál es el orden de los tres saltos del salto triple?", "opciones": {"A": "Brinco, paso y salto", "B": "Salto, paso y brinco", "C": "Paso, brinco y salto", "D": "Brinco, salto y paso"}}, {"n": 14, "seccion": 2, "competencia": "Literal", "enunciado": "¿Con qué termina el salto triple?", "opciones": {"A": "Con una caída sobre un solo pie", "B": "Con una caída sobre las manos", "C": "Con una caída con ambos pies en la arena", "D": "Con una caída de espaldas al foso"}}, {"n": 15, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, «listón» es", "opciones": {"A": "la tabla de batida", "B": "el foso de arena", "C": "el traje del saltador", "D": "la barra horizontal que se debe superar sin derribar"}}, {"n": 16, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué la zona de caída debe ser blanda?", "opciones": {"A": "Para que los saltos sean más largos", "B": "Para que se vea mejor la huella", "C": "Para que el juez no se canse", "D": "Para amortiguar el impacto y evitar lesiones"}}, {"n": 17, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un atleta falla dos veces a 1,40 m, logra la tercera, y luego falla dos veces a 1,45 m. ¿Sigue en competencia?", "opciones": {"A": "No, ya quedó eliminado", "B": "No, porque falló en dos alturas distintas", "C": "Sí, le queda un intento a 1,45 m", "D": "Sí, y le quedan tres intentos nuevos"}}, {"n": 18, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un compañero cae con ambos pies en el primer salto del salto triple. ¿Qué debe corregir?", "opciones": {"A": "Debe caer de espaldas", "B": "Debe saltar primero con los dos pies en cada fase", "C": "Nada, así es el salto triple", "D": "El primer salto debe caer en el mismo pie con el que despegó"}}, {"n": 19, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué es importante que todos los saltadores sean medidos con las mismas reglas?", "opciones": {"A": "Porque así gana siempre el mismo", "B": "Porque así los resultados se pueden comparar de forma justa", "C": "Porque el juez se confunde menos con reglas distintas", "D": "Porque las reglas no importan si hay buen público"}}, {"n": 20, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Un estudiante dice que el salto triple es más fácil que el alto porque «son tres saltos». ¿Cuál es el mejor argumento en contra?", "opciones": {"A": "Que el salto triple no se mide", "B": "Que el salto alto no tiene reglas", "C": "Cada prueba exige su propia técnica: el triple coordina tres fases con caída precisa y el alto requiere un despegue y paso preciso sobre el listón", "D": "Que en el triple no hace falta calentar"}}]}, {"id": "2027-g8-p2-quiz1", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Fundamentos (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "En el toque de dedos, el balón se golpea", "opciones": {"A": "a la altura de las rodillas", "B": "por encima de la frente", "C": "con los puños cerrados", "D": "con una sola mano"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "El golpe de antebrazos se usa principalmente para", "opciones": {"A": "rematar", "B": "bloquear", "C": "recibir el saque o defender", "D": "sacar"}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "Si el balón llega bajo y rápido, la postura adecuada es", "opciones": {"A": "rodillas flexionadas y brazos extendidos y unidos", "B": "brazos arriba y piernas rectas", "C": "brazos cruzados", "D": "de espaldas a la red"}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "El bloqueo consiste en", "opciones": {"A": "golpear el balón desde atrás de la línea", "B": "dejar caer el balón", "C": "pasar el balón al otro lado con el pie", "D": "elevar los brazos frente a la red para frenar un remate"}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué practicar los fundamentos antes de jugar un partido?", "opciones": {"A": "Porque mejora el control del balón y hace el juego más continuo y seguro", "B": "Porque así no hace falta calentar", "C": "Porque se evita el trabajo en equipo", "D": "Porque los partidos no necesitan técnica"}}]}, {"id": "2027-g8-p2-quiz2", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Reglas (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores de cada equipo están en la cancha?", "opciones": {"A": "Seis", "B": "Cinco", "C": "Siete", "D": "Ocho"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos toques puede dar un equipo antes de devolver el balón?", "opciones": {"A": "Dos", "B": "Cuatro", "C": "Cinco", "D": "Tres"}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un equipo recupera el saque. ¿Qué hacen sus jugadores?", "opciones": {"A": "Cambian de cancha", "B": "Descansan un set", "C": "Rotan una posición en el sentido de las manecillas del reloj", "D": "Mantienen siempre la misma posición"}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador toca la red con el cuerpo mientras la jugada sigue en marcha. Esto es", "opciones": {"A": "una jugada válida", "B": "una falta", "C": "un punto para su equipo", "D": "un descanso"}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Tras un punto discutido, ¿qué actitud muestra juego limpio?", "opciones": {"A": "Aceptar la decisión del árbitro y seguir con respeto", "B": "Discutir hasta que cambie la decisión", "C": "Dejar de jugar", "D": "Culpar a un compañero"}}]}, {"id": "2027-g8-p2", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 2", "titulo": "Evaluación tipo Saber — Voleibol: fundamentos y reglas básicas (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 25, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Los fundamentos del voleibol", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El voleibol se juega entre dos equipos de seis jugadores separados por una red. Para mantener el balón en el aire se usan fundamentos técnicos. El toque de dedos se hace por encima de la frente, con las manos formando una «ventana», y sirve para colocar el balón a una compañera o compañero. El golpe de antebrazos, o «bobito», se usa para recibir el saque o defender: los brazos se extienden unidos, las rodillas se flexionan y el balón se golpea con la parte plana de los antebrazos, sin levantar los brazos por encima de los hombros. El saque inicia cada jugada y se ejecuta desde detrás de la línea de fondo. El remate es el golpe fuerte, dado con una mano cerca de la red, para enviar el balón al campo contrario; el bloqueo consiste en elevar los brazos frente a la red para frenarlo. Un equipo puede tocar el balón hasta tres veces antes de devolverlo, y ningún jugador puede tocarlo dos veces seguidas, con excepción del bloqueo."}, {"id": 2, "titulo": "Reglas básicas y puntuación", "instruccion": "(Responda las preguntas 11 a 20 con base en el siguiente texto.)", "cuerpo": "La cancha de voleibol mide 18 metros de largo por 9 de ancho, y la red se ubica en el centro. Cada equipo ubica seis jugadores: tres adelante y tres atrás. Cuando un equipo recupera el saque, sus jugadores rotan una posición en el sentido de las manecillas del reloj. En el sistema actual, cada jugada o rally otorga un punto al equipo que la gana, sin importar quién sacó. Los sets se juegan a 25 puntos con una diferencia mínima de dos; el partido lo gana quien primero gane tres sets, y si se llega a un quinto set, este se juega a 15 puntos. Son faltas comunes tocar la red durante la jugada, cometer un doble toque, retener o acompañar el balón, o dejar que el balón caiga dentro de la propia cancha. El balón que cae sobre una línea se considera dentro."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores tiene cada equipo en la cancha?", "opciones": {"A": "Cuatro", "B": "Seis", "C": "Cinco", "D": "Siete"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué fundamento se usa para recibir el saque?", "opciones": {"A": "El remate", "B": "El bloqueo", "C": "El golpe de antebrazos", "D": "El toque de dedos"}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Desde dónde se ejecuta el saque?", "opciones": {"A": "Desde la red", "B": "Desde detrás de la línea de fondo", "C": "Desde la mitad de la cancha", "D": "Desde cualquier lado de la cancha"}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos toques puede dar un equipo antes de devolver el balón?", "opciones": {"A": "Hasta tres", "B": "Hasta dos", "C": "Hasta cuatro", "D": "Los que necesite"}}, {"n": 5, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «colocar» el balón significa", "opciones": {"A": "sentarlo en el piso", "B": "sacarlo de la cancha", "C": "enviarlo con precisión a un compañero", "D": "devolverlo de inmediato al otro equipo"}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué se flexionan las rodillas al golpear con los antebrazos?", "opciones": {"A": "Para dar estabilidad y controlar la dirección usando las piernas, no solo los brazos", "B": "Para que el balón se quede quieto", "C": "Para evitar el contacto con la red", "D": "Porque lo exige el árbitro"}}, {"n": 7, "seccion": 1, "competencia": "Aplicación", "enunciado": "Recibes un saque fuerte a la altura de la cintura. ¿Qué fundamento conviene usar?", "opciones": {"A": "El remate", "B": "El toque de dedos por encima de la frente", "C": "El bloqueo", "D": "El golpe de antebrazos"}}, {"n": 8, "seccion": 1, "competencia": "Aplicación", "enunciado": "Tu compañera te pasa un balón alto cerca de la red y quieres atacar. ¿Qué fundamento aplicas?", "opciones": {"A": "El saque", "B": "El remate", "C": "El golpe de antebrazos de espaldas", "D": "El bloqueo"}}, {"n": 9, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Para qué sirve limitar los toques a tres por equipo?", "opciones": {"A": "Obliga a organizar la jugada entre varios: recibir, colocar y atacar", "B": "Para que el partido dure menos", "C": "Para que solo jueguen los mejores", "D": "Para que nadie pueda rematar"}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un equipo devuelve el balón siempre en el primer toque. Según el texto, ¿qué desaprovecha?", "opciones": {"A": "El derecho a sacar", "B": "La red, que estorba el juego", "C": "El tiempo de descanso", "D": "La posibilidad de organizar un ataque recibiendo, colocando y rematando"}}, {"n": 11, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuáles son las medidas de la cancha de voleibol?", "opciones": {"A": "9 metros de largo por 18 de ancho", "B": "20 metros de largo por 10 de ancho", "C": "12 metros de largo por 6 de ancho", "D": "18 metros de largo por 9 de ancho"}}, {"n": 12, "seccion": 2, "competencia": "Literal", "enunciado": "¿A cuántos puntos se juega un set normal?", "opciones": {"A": "A 15, con diferencia de uno", "B": "A 21, sin diferencia", "C": "A 25, con diferencia mínima de dos", "D": "A 30, con diferencia de tres"}}, {"n": 13, "seccion": 2, "competencia": "Literal", "enunciado": "¿En qué sentido rotan los jugadores?", "opciones": {"A": "En el sentido de las manecillas del reloj", "B": "En sentido contrario a las manecillas", "C": "De un lado a otro de la red", "D": "Solo los jugadores de atrás"}}, {"n": 14, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cómo se considera un balón que cae sobre la línea?", "opciones": {"A": "Fuera", "B": "Dentro", "C": "Nulo, se repite la jugada", "D": "Depende de quién sacó"}}, {"n": 15, "seccion": 2, "competencia": "Inferencial", "enunciado": "La frase «sin importar quién sacó» indica que", "opciones": {"A": "el equipo que no sacó también puede ganar el punto", "B": "solo el equipo que saca puede sumar", "C": "el saque no vale puntos", "D": "los puntos se reparten por igual"}}, {"n": 16, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué se exige una diferencia de dos puntos para ganar un set?", "opciones": {"A": "Para alargar el partido sin razón", "B": "Para que gane siempre el que saca", "C": "Para que el ganador demuestre una ventaja clara sobre el rival", "D": "Porque la cancha es muy grande"}}, {"n": 17, "seccion": 2, "competencia": "Aplicación", "enunciado": "El marcador está 24 a 24. ¿Qué pasa?", "opciones": {"A": "El set termina en empate", "B": "Gana el equipo que sacó último", "C": "El set continúa hasta que un equipo tenga ventaja de dos puntos", "D": "Se juega un solo punto más"}}, {"n": 18, "seccion": 2, "competencia": "Aplicación", "enunciado": "Una jugadora golpea el balón dos veces seguidas. ¿Qué se sanciona?", "opciones": {"A": "Nada, es jugada legal", "B": "Un saque anulado sin punto", "C": "Una falta por tocar la red", "D": "Doble toque, y el punto es del rival"}}, {"n": 19, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué el reglamento prohíbe retener el balón?", "opciones": {"A": "Porque el balón es frágil", "B": "Porque el voleibol se basa en golpearlo sin dominarlo, lo que mantiene el juego dinámico y justo", "C": "Porque retener da puntos", "D": "Porque así se evitan los saques"}}, {"n": 20, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Si el curso tiene poco tiempo para un partido, ¿qué decisión es más razonable?", "opciones": {"A": "Quitar la red", "B": "Permitir tocar el balón varias veces seguidas", "C": "No contar los puntos", "D": "Jugar un set a 15 puntos acordado por todos, conservando las reglas básicas"}}]}, {"id": "2027-g9-p2-quiz1", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 2", "titulo": "Quiz 1 — Reglas del futsal (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "El balón del futsal se caracteriza por", "opciones": {"A": "ser más grande que el de campo", "B": "tener menos rebote que el de fútbol de campo", "C": "ser el mismo en todo", "D": "rebotar muy alto"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores de cada equipo hay en la cancha?", "opciones": {"A": "Cinco, incluido el portero", "B": "Siete, incluido el portero", "C": "Nueve", "D": "Once"}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "Debes ejecutar un saque de esquina en futsal. ¿Cómo lo haces?", "opciones": {"A": "Con las manos", "B": "Con la cabeza", "C": "Con el pie", "D": "Con el pecho"}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero necesita descansar durante el partido. ¿Cómo se hace el cambio?", "opciones": {"A": "Se detiene el partido por 10 minutos", "B": "No se permiten cambios", "C": "Solo en el entretiempo", "D": "Entra un sustituto con el juego en marcha por la zona de cambios"}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Para qué sirve el tiempo muerto?", "opciones": {"A": "Para descansar y organizar la táctica", "B": "Para cambiar el reglamento", "C": "Para anotar un gol", "D": "Para sancionar al rival"}}]}, {"id": "2027-g9-p2-quiz2", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 2", "titulo": "Quiz 2 — Fundamentos y sistemas (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 10, "puntosPorPregunta": 1, "modalidad": "Quiz", "textos": [], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "El pase con el interior del pie se usa porque ofrece", "opciones": {"A": "mayor precisión", "B": "más fuerza que cualquier otro", "C": "menos control", "D": "mayor altura"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "El control con la planta del pie sirve para", "opciones": {"A": "patear con potencia", "B": "detener el balón a ras de piso", "C": "rematar de cabeza", "D": "levantar el balón"}}, {"n": 3, "seccion": 1, "competencia": "Aplicación", "enunciado": "Si quieres un sistema con un cierre, dos alas y un pívot, eliges", "opciones": {"A": "el cuadro (2-2)", "B": "el 4-0 sin portero", "C": "el rombo (1-2-1)", "D": "un sistema sin orden"}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Para quitar el balón sin cometer falta, lo más correcto es", "opciones": {"A": "interponerse y anticipar el pase, sin empujar ni patear", "B": "empujar al rival por la espalda", "C": "hacer zancadilla", "D": "jalar la camiseta"}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál de estas actitudes muestra juego limpio?", "opciones": {"A": "Fingir una lesión para ganar tiempo", "B": "Reclamar todas las decisiones al árbitro", "C": "Ocultar el balón al rival", "D": "Reconocer una falta propia y ayudar al rival caído"}}]}, {"id": "2027-g9-p2", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 2", "titulo": "Evaluación tipo Saber — Futsal: reglas, fundamentos y sistemas de juego (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 25, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Qué es el futsal", "instruccion": "(Responda las preguntas 1 a 10 con base en el siguiente texto.)", "cuerpo": "El futsal o fútbol sala es una modalidad de fútbol que se juega en cancha cubierta y pequeña entre dos equipos de cinco jugadores, uno de ellos el portero. El balón es más pequeño y tiene menos rebote que el de fútbol de campo, lo que favorece el control con la planta del pie y el pase corto. El partido se divide en dos tiempos de 20 minutos con el reloj detenido cuando el balón no está en juego, es decir, en tiempo neto. Las sustituciones son ilimitadas y se hacen con el juego en marcha por una zona determinada. Cada equipo puede pedir un tiempo muerto por tiempo. Los saques de banda y de esquina se ejecutan con el pie, y quien los realiza tiene cuatro segundos para reanudar el juego. Estas diferencias hacen que el futsal sea rápido, con muchos toques de balón y decisiones en poco espacio."}, {"id": 2, "titulo": "Faltas, sanciones y sistemas de juego", "instruccion": "(Responda las preguntas 11 a 20 con base en el siguiente texto.)", "cuerpo": "Las faltas en futsal se sancionan con tiro libre. Las faltas que comete un equipo se acumulan en cada tiempo, y desde la sexta falta acumulada cada nueva falta se castiga con un tiro libre directo sin barrera. La tarjeta amarilla es una advertencia; la roja expulsa al jugador, pero su equipo puede reemplazarlo después de dos minutos o cuando el rival marque un gol. El portero puede jugar con los pies como un compañero más, pero no puede tomar con las manos un pase con el pie de un compañero. En cuanto a los sistemas, el 2-2 o cuadro ubica a dos jugadores atrás y dos adelante, mientras que el 1-2-1 o rombo ubica un cierre, dos alas y un pívot. Cada sistema busca equilibrar la defensa y el ataque según las cualidades del equipo."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores forman un equipo en el campo, incluido el portero?", "opciones": {"A": "Cinco", "B": "Siete", "C": "Nueve", "D": "Once"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se juega el tiempo en el futsal?", "opciones": {"A": "Dos tiempos de 20 minutos con el reloj detenido cuando el balón no está en juego", "B": "Un solo tiempo de 90 minutos corridos", "C": "Cuatro tiempos de 10 minutos corridos", "D": "Dos tiempos de 45 minutos corridos"}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo se ejecuta el saque de banda en el futsal?", "opciones": {"A": "Con las dos manos sobre la cabeza", "B": "Con una mano", "C": "Con el pie", "D": "Con la cabeza"}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "¿De cuánto tiempo dispone un jugador para reanudar el juego en un saque?", "opciones": {"A": "Un minuto", "B": "Cuatro segundos", "C": "Diez segundos", "D": "Dos minutos"}}, {"n": 5, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, «tiempo neto» significa", "opciones": {"A": "que el partido dura solo 20 minutos en total", "B": "que se cuentan solo los goles", "C": "que el árbitro decide cuánto dura", "D": "que el reloj se detiene cuando el balón no está en juego"}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el balón con menos rebote favorece el pase corto y el control?", "opciones": {"A": "Porque se mantiene más cerca del piso y es más fácil de controlar", "B": "Porque es más pesado que cualquier balón", "C": "Porque rebota más alto", "D": "Porque no necesita ser controlado"}}, {"n": 7, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Cómo ayudan las sustituciones ilimitadas a que el juego sea rápido?", "opciones": {"A": "Hacen que el partido dure más", "B": "Impiden los cambios tácticos", "C": "Permiten que entren jugadores descansados y se mantenga la intensidad", "D": "Eliminan los tiempos muertos"}}, {"n": 8, "seccion": 1, "competencia": "Aplicación", "enunciado": "Debes sacar de banda en un partido de futsal. ¿Qué haces?", "opciones": {"A": "Lo lanzas con las manos desde atrás de la cabeza", "B": "Colocas el balón en la línea y lo reanudas con el pie en cuatro segundos", "C": "Esperas a que el árbitro cuente un minuto", "D": "Lo sacas con la cabeza"}}, {"n": 9, "seccion": 1, "competencia": "Aplicación", "enunciado": "Tu equipo va ganando pero está cansado y desorganizado. ¿Qué puede pedir el entrenador?", "opciones": {"A": "Un cambio de cancha", "B": "Una pausa de 20 minutos", "C": "Terminar el partido", "D": "Un tiempo muerto"}}, {"n": 10, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué el futsal es adecuado para clases con poco espacio?", "opciones": {"A": "Porque se juega sin reglas", "B": "Porque se juega en cancha pequeña y exige muchos toques y participación de todos", "C": "Porque solo necesita dos jugadores", "D": "Porque no requiere balón"}}, {"n": 11, "seccion": 2, "competencia": "Literal", "enunciado": "¿Desde qué falta acumulada se sanciona con tiro libre directo sin barrera?", "opciones": {"A": "Desde la primera", "B": "Desde la décima", "C": "Desde la sexta", "D": "Desde la tercera"}}, {"n": 12, "seccion": 2, "competencia": "Literal", "enunciado": "Si un jugador recibe la tarjeta roja,", "opciones": {"A": "es expulsado y su equipo puede reemplazarlo tras dos minutos o un gol del rival", "B": "su equipo juega con uno menos el resto del partido", "C": "solo debe salir cinco minutos", "D": "se repite el partido"}}, {"n": 13, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cómo se ubican los jugadores en el sistema 2-2?", "opciones": {"A": "Tres atrás y uno adelante", "B": "Uno atrás y tres adelante", "C": "Cuatro atrás", "D": "Dos atrás y dos adelante"}}, {"n": 14, "seccion": 2, "competencia": "Literal", "enunciado": "¿Qué limitación tiene el portero con los pases de sus compañeros?", "opciones": {"A": "No puede salir del área", "B": "No puede usar los pies", "C": "No puede recibir pases", "D": "No puede tomar con las manos un pase con el pie de un compañero"}}, {"n": 15, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, «acumuladas» significa", "opciones": {"A": "anuladas por el árbitro", "B": "sumadas a lo largo del tiempo", "C": "cometidas por el portero", "D": "cometidas por el rival"}}, {"n": 16, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Para qué sirve sancionar con más fuerza las faltas acumuladas?", "opciones": {"A": "Para alargar el partido", "B": "Para desalentar el juego brusco repetido", "C": "Para que el portero juegue más", "D": "Para que no haya faltas pequeñas"}}, {"n": 17, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Qué consecuencia tiene que el equipo pueda reemplazar al expulsado solo tras dos minutos o un gol?", "opciones": {"A": "El equipo no se ve afectado", "B": "El rival queda sancionado", "C": "La falta afecta a todo el equipo, no solo al jugador expulsado", "D": "El partido se detiene"}}, {"n": 18, "seccion": 2, "competencia": "Aplicación", "enunciado": "Tu equipo lleva cinco faltas acumuladas en el primer tiempo y comete otra. ¿Qué se sanciona?", "opciones": {"A": "Un tiro de esquina", "B": "Un saque de banda", "C": "Nada, aún no es sancionable", "D": "Un tiro libre directo sin barrera"}}, {"n": 19, "seccion": 2, "competencia": "Aplicación", "enunciado": "Quieren armar un rombo (1-2-1). ¿Cómo ubican a los jugadores?", "opciones": {"A": "Dos atrás y dos adelante", "B": "Cuatro delanteros", "C": "Un cierre, dos alas y un pívot", "D": "Cuatro defensas"}}, {"n": 20, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "Un compañero dice que hacer faltas tácticas siempre es válido para detener al rival. ¿Qué respuesta es más acertada?", "opciones": {"A": "Puede frenar una jugada, pero acumula castigos y va contra el juego limpio", "B": "Siempre ayuda a ganar", "C": "El reglamento no sanciona las faltas", "D": "Solo importa si el árbitro no ve"}}]}];
